-- =====================================================================
-- Learner v4: Thompson sampling from the first table, and the guest's
-- language as context (supabase/tests/reco-learner-v4.test.ts,
-- supabase/tests/reco-simulator.test.ts)
-- =====================================================================
--
-- GENERATED by C:\Users\kerim\pass2-scratch\reco\gen_v4.py from the live
-- ranker (20261031120000_reco_quality.sql), maybe_enable_sampling
-- (20261028100000_two_restaurants_context.sql) and refresh_menu_intelligence
-- (20261031100000_admin_separation.sql): those bodies are copied verbatim and
-- every change is marked "v4".
--
-- What the ranker did: it ranked by P(taken) x margin blended with the house
-- priority, P(taken) being the MEAN of each pair's Bayesian record. To try
-- new pairs it added a bonus that depended only on how often a dish had been
-- shown (0.15 x 30/(30+shown) x a hashed draw): a pair plainly bad after 40
-- sightings kept getting impressions, and a promising 3-in-5 got no more than
-- any other. Thompson sampling, which allocates sightings by how likely each
-- pair is to be best, was built but switched off behind a gate (2000
-- decisions, 15 pairs with 50 sightings) that Vera Italia would not pass for
-- months. And the language the guest reads the menu in — locals in Bosnian,
-- Gulf visitors in Arabic, the rest in English — was sent with every request
-- and ignored.
--
-- DEFAULT: v3. Applying this file changes nothing guests see: the ranker
-- stays v3 (restaurant_settings.reco_learner = 'v3') and no experiment is
-- closed. What it does add for everyone is the guest's language on every
-- decision and the per-language record, so v4 has data the day it is tried.
-- In the offline simulator (supabase/tests/reco-simulator.test.ts, 3 seeds ×
-- 6 weeks × 36 tables a day on La Soul's real menu) v4 earned 5% less margin
-- per table than v3 where languages differ in taste and 2% less where they
-- do not: its posterior draw explores more than v3's bounded novelty bonus,
-- and six weeks of one café is too little data per language for the
-- context to pay that back. Switch a restaurant with
--   UPDATE public.restaurant_settings SET reco_learner = 'v4' WHERE venue_id = ...;
-- (a trigger closes that restaurant's running experiment: a policy change).
--
-- v4 (opt-in; 'v3' runs the old ranker exactly as it was):
--   1. P(taken) is a draw from each candidate's posterior (reco_posterior_v4),
--      seeded by the table session so the card does not change while a guest
--      looks; how far from the mean is the exploration dial that already
--      exists (reco_exploration: 15 = a full Thompson draw, 0 = the mean, so a
--      cautious owner and the deterministic tests keep a fixed ranking). The
--      novelty bonus is gone. Everything else in the score — the house
--      priority, what tables taught it, expected profit, the penalties — and
--      every guardrail, fit rule and head-waiter rule is unchanged.
--   2. The posterior knows the guest's language: dish in this language (over
--      every pair), then the pair in the other languages, then the pair in
--      this language, each level shrunk to the one above (a pair's languages
--      may differ by about what 40 sightings would show). With no language
--      record it is the old posterior; tourists and locals get different
--      first cards only once their own record says so.
--   3. Every decision records the language; refresh_menu_intelligence also
--      rebuilds suggestion_context_stats (sightings and paid takes per pair
--      or dish, placement and language, 90 days, from the ledger).
--   4. The ledger's probability is that of the choice under the sampling in
--      force (200 joint posterior draws), and each candidate's posterior mean
--      and spread are stored with the decision, so the policy can be evaluated
--      off-policy later.
--   5. Policy version 'v4-thompson-context'. maybe_enable_sampling() has
--      nothing to switch under v4 and no longer closes the experiment for it.
--      Changing reco_learner closes the restaurant's running experiment (a
--      policy change starts a new one); the always-on check
--      (20261116120000_reco_always_measured.sql) opens the next.
--
-- The signatures of reco_rank_scored, rank_recommendations and
-- guest_get_recommendations are unchanged. Additive otherwise: two columns,
-- one table, new functions. Safe to run twice. Runs after
-- 20261116120000_reco_always_measured.sql.

-- ---------------------------------------------------------------------
-- 0. Columns and the per-language record
-- ---------------------------------------------------------------------

ALTER TABLE public.restaurant_settings
  ADD COLUMN IF NOT EXISTS reco_learner text NOT NULL DEFAULT 'v3';

DO $chk$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'restaurant_settings_reco_learner_check') THEN
    ALTER TABLE public.restaurant_settings
      ADD CONSTRAINT restaurant_settings_reco_learner_check CHECK (reco_learner IN ('v3', 'v4'));
  END IF;
END
$chk$;

COMMENT ON COLUMN public.restaurant_settings.reco_learner IS
  'Suggestion ranker: v3 (default) = the ranker of 20261031120000; v4 = Thompson sampling with the guest''s language as context (20261116130000), opt-in: it did not beat v3 in the offline simulator.';

/** The language the guest read the menu in when the decision was made. */
ALTER TABLE public.recommendation_decisions
  ADD COLUMN IF NOT EXISTS language text;

/**
 * Sightings and paid takes per (pair or dish, placement, language), from the
 * ledger, 90 days. scope 'pair': one source dish; scope 'dish': every source.
 * Rebuilt by refresh_suggestion_context_stats().
 */
CREATE TABLE IF NOT EXISTS public.suggestion_context_stats (
  scope text NOT NULL CHECK (scope IN ('pair', 'dish')),
  recommended_item_id uuid NOT NULL REFERENCES public.menu_items(id) ON DELETE CASCADE,
  source_item_id uuid,
  placement text NOT NULL,
  context text NOT NULL,
  shown int NOT NULL DEFAULT 0,
  accepted int NOT NULL DEFAULT 0,
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS suggestion_context_stats_key
  ON public.suggestion_context_stats(scope, recommended_item_id,
                                     COALESCE(source_item_id, '00000000-0000-0000-0000-000000000000'::uuid),
                                     placement, context);

-- Access first, then row level security, then the policy (the order Lovable
-- applies; supabase/tests/migration-grants.test.ts). Written only by the
-- SECURITY DEFINER refresh; staff may read it.
REVOKE ALL ON public.suggestion_context_stats FROM PUBLIC, anon;
GRANT SELECT ON public.suggestion_context_stats TO authenticated;
GRANT ALL ON public.suggestion_context_stats TO service_role;

ALTER TABLE public.suggestion_context_stats ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Staff read suggestion context stats" ON public.suggestion_context_stats;
CREATE POLICY "Staff read suggestion context stats" ON public.suggestion_context_stats
  FOR SELECT TO authenticated USING (public.is_staff_member());

-- ---------------------------------------------------------------------
-- 1. Which ranker, and its version
-- ---------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.reco_learner_for(_venue uuid)
RETURNS text
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT COALESCE((SELECT reco_learner FROM public.restaurant_settings WHERE venue_id = _venue), 'v3');
$$;

REVOKE ALL ON FUNCTION public.reco_learner_for(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.reco_learner_for(uuid) TO anon, authenticated;

-- Latest: 20261116120000_reco_always_measured.sql.
CREATE OR REPLACE FUNCTION public.reco_policy_version_for(_venue uuid)
RETURNS text
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT CASE
    WHEN public.reco_learner_for(_venue) = 'v4' THEN 'v4-thompson-context'
    WHEN COALESCE((SELECT reco_sampling_enabled FROM public.restaurant_settings
                    WHERE venue_id = _venue), false)
    THEN 'v3-profit-thompson'
    ELSE 'v3-profit'
  END;
$$;

/** Switching the ranker is a policy change: the running experiment closes. */
CREATE OR REPLACE FUNCTION public.trg_reco_learner_changed()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.reco_learner IS DISTINCT FROM OLD.reco_learner THEN
    UPDATE public.experiments
       SET ended_at = now(),
           notes = COALESCE(notes || ' ', '') || '[closed: ranking policy changed to '
                   || public.reco_policy_version_for(NEW.venue_id) || ']'
     WHERE ended_at IS NULL AND venue_id = NEW.venue_id;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION public.trg_reco_learner_changed() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS trg_reco_learner_changed ON public.restaurant_settings;
CREATE TRIGGER trg_reco_learner_changed
  AFTER UPDATE OF reco_learner ON public.restaurant_settings
  FOR EACH ROW EXECUTE FUNCTION public.trg_reco_learner_changed();

-- ---------------------------------------------------------------------
-- 2. The per-language record, rebuilt from the ledger
-- ---------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.refresh_suggestion_context_stats(_days int DEFAULT 90)
RETURNS int
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_rows int;
BEGIN
  IF NOT public.is_trusted_caller() THEN
    RAISE EXCEPTION 'Only staff can refresh suggestion statistics' USING ERRCODE = 'insufficient_privilege';
  END IF;

  DELETE FROM public.suggestion_context_stats;

  WITH d AS (
    SELECT d.chosen_item_id, d.source_item_id, d.placement, 'lang:' || d.language AS context,
           EXISTS (SELECT 1 FROM public.suggestion_conversions sc
                     JOIN public.completed_orders co ON co.id = sc.order_id
                    WHERE sc.decision_id = d.id) AS took,
           EXISTS (SELECT 1 FROM public.recommendation_impressions i WHERE i.decision_id = d.id) AS seen
      FROM public.recommendation_decisions d
     WHERE d.created_at > now() - make_interval(days => GREATEST(COALESCE(_days, 90), 1))
       AND d.chosen_item_id IS NOT NULL
       AND d.language IN ('en', 'bs', 'ar')
  ),
  pairs AS (
    SELECT 'pair'::text AS scope, chosen_item_id, source_item_id, placement, context,
           count(*) FILTER (WHERE seen OR took)::int AS shown, count(*) FILTER (WHERE took)::int AS accepted
      FROM d GROUP BY chosen_item_id, source_item_id, placement, context
  ),
  dishes AS (
    SELECT 'dish'::text AS scope, chosen_item_id, NULL::uuid AS source_item_id, placement, context,
           count(*) FILTER (WHERE seen OR took)::int AS shown, count(*) FILTER (WHERE took)::int AS accepted
      FROM d GROUP BY chosen_item_id, placement, context
  )
  INSERT INTO public.suggestion_context_stats(scope, recommended_item_id, source_item_id, placement, context, shown, accepted)
  SELECT * FROM pairs WHERE shown > 0
  UNION ALL
  SELECT * FROM dishes WHERE shown > 0;

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows;
END;
$$;

REVOKE ALL ON FUNCTION public.refresh_suggestion_context_stats(int) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.refresh_suggestion_context_stats(int) TO authenticated;

-- ---------------------------------------------------------------------
-- 3. The posterior, with the language
-- ---------------------------------------------------------------------

/**
 * P(taken) for one pair at one placement, for a guest reading in _lang, as a
 * Beta(alpha, beta), its mean and spread, and a standard normal draw z seeded
 * by _seed (the table session) for the ranker to use as mean + k·z·sd.
 *
 *   dish prior            suggestion_prior (the dish here, elsewhere)       m0, n0
 *   dish in this language Beta(20·m0 + taken, 20·(1−m0) + not)              m_dl
 *   pair, other languages Beta(n0·m_dl + taken, n0·(1−m_dl) + not)          from suggestion_stats
 *                         (this daypart's row where it exists), less this language's own
 *   pair, this language   Beta(κ·m_p + taken, κ·(1−m_p) + not),  κ = min(strength above, 40)
 *
 * With no language record anywhere it is the pair's posterior as v3 had it
 * (strength capped at 40: a language may still turn out different).
 */
CREATE OR REPLACE FUNCTION public.reco_posterior_v4(
  _item_id uuid, _placement text, _source_item_id uuid, _daypart text, _lang text, _seed text
)
RETURNS TABLE(mean numeric, sd numeric, z numeric, alpha numeric, beta numeric)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  WITH pr AS (
    SELECT p.alpha0, p.beta0, p.alpha0 / NULLIF(p.alpha0 + p.beta0, 0) AS m0, p.alpha0 + p.beta0 AS n0
      FROM public.suggestion_prior(_item_id, _placement) p
  ),
  ctx AS (SELECT 'lang:' || CASE WHEN _lang IN ('en', 'bs', 'ar') THEN _lang ELSE 'en' END AS c),
  dl AS (
    SELECT COALESCE(sum(cs.shown), 0)::numeric AS shown, COALESCE(sum(cs.accepted), 0)::numeric AS acc
      FROM public.suggestion_context_stats cs, ctx
     WHERE cs.scope = 'dish' AND cs.recommended_item_id = _item_id
       AND cs.placement = _placement AND cs.context = ctx.c
  ),
  pl AS (
    SELECT COALESCE(sum(cs.shown), 0)::numeric AS shown, COALESCE(sum(cs.accepted), 0)::numeric AS acc
      FROM public.suggestion_context_stats cs, ctx
     WHERE cs.scope = 'pair' AND cs.recommended_item_id = _item_id
       AND cs.source_item_id IS NOT DISTINCT FROM _source_item_id
       AND cs.placement = _placement AND cs.context = ctx.c
  ),
  rows AS (
    SELECT st.daypart, st.accepted, st.shown
      FROM public.suggestion_stats st
     WHERE st.recommended_item_id = _item_id
       AND st.placement = _placement
       AND st.source_item_id IS NOT DISTINCT FROM _source_item_id
       AND (st.daypart = _daypart OR st.daypart IS NULL)
  ),
  pair AS (
    SELECT COALESCE((SELECT shown FROM rows WHERE daypart = _daypart), (SELECT shown FROM rows WHERE daypart IS NULL), 0)::numeric AS shown,
           COALESCE((SELECT accepted FROM rows WHERE daypart = _daypart), (SELECT accepted FROM rows WHERE daypart IS NULL), 0)::numeric AS acc
  ),
  lvl AS (
    SELECT pr.n0,
           (20 * COALESCE(pr.m0, 1.0 / 13) + dl.acc) / (20 + dl.shown) AS m_dl,
           GREATEST(pair.shown - pl.shown, 0) AS o_shown,
           LEAST(GREATEST(pair.acc - pl.acc, 0), GREATEST(pair.shown - pl.shown, 0)) AS o_acc,
           pl.shown AS l_shown, LEAST(pl.acc, pl.shown) AS l_acc
      FROM pr, dl, pl, pair
  ),
  parent AS (
    SELECT l.*, l.n0 * l.m_dl + l.o_acc AS a, l.n0 * (1 - l.m_dl) + (l.o_shown - l.o_acc) AS b FROM lvl l
  ),
  post AS (
    SELECT LEAST(a + b, 40) * a / (a + b) + l_acc AS a2,
           LEAST(a + b, 40) * b / (a + b) + (l_shown - l_acc) AS b2
      FROM parent
  ),
  u AS (
    SELECT * FROM public.hash_uniforms(COALESCE(_seed, 'anon') || ':v4:' || _item_id::text || ':'
                                       || COALESCE(_source_item_id::text, '') || ':' || COALESCE(_placement, ''))
  )
  SELECT round(post.a2 / (post.a2 + post.b2), 6),
         round(sqrt(post.a2 * post.b2 / ((post.a2 + post.b2) * (post.a2 + post.b2) * (post.a2 + post.b2 + 1))), 6),
         round((sqrt(-2 * ln(u.u1)) * cos(2 * pi() * u.u2))::numeric, 6),
         round(post.a2, 4), round(post.b2, 4)
    FROM post, u;
$$;

REVOKE ALL ON FUNCTION public.reco_posterior_v4(uuid, text, uuid, text, text, text) FROM PUBLIC, anon, authenticated;

-- ---------------------------------------------------------------------
-- 4. Today's ranker, kept as v3 (verbatim from 20261031120000_reco_quality.sql)
-- ---------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.reco_rank_scored_v3(_cart_item_ids uuid[] DEFAULT '{}'::uuid[], _placement text DEFAULT 'cart'::text, _language text DEFAULT 'en'::text, _limit integer DEFAULT 4, _session_id uuid DEFAULT NULL::uuid, _exclude_allergens text[] DEFAULT '{}'::text[], _cart_quantities integer[] DEFAULT NULL::integer[])
 RETURNS TABLE(id uuid, name text, name_bs text, name_ar text, price numeric, image_url text, dietary_tags text[], recommendation_type text, reason text, source_item_id uuid, suggested_quantity integer, score numeric, explore numeric, explore_room numeric, grp text, kind text, curated_score numeric, learned_score numeric, observed_score numeric, evidence numeric, p_accept numeric, ord integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH here AS (
    SELECT public.current_venue() AS venue
  ),
  s AS (
    SELECT
      COALESCE(recommendations_enabled, true) AS enabled,
      COALESCE(reco_weight_curated, 40)::numeric  / 100 AS w_curated,
      COALESCE(reco_weight_observed, 25)::numeric / 100 AS w_observed,
      (COALESCE(reco_weight_learned, 25) + COALESCE(reco_weight_margin, 10))::numeric / 100 AS w_value,
      COALESCE(reco_exploration, 15)::numeric     / 100 AS w_explore,
      COALESCE(reco_min_acceptance, 0.03)               AS min_acceptance,
      COALESCE(reco_retire_after_impressions, 60)       AS retire_after
    FROM public.restaurant_settings WHERE venue_id = (SELECT venue FROM here)
  ),
  -- Only this restaurant's dishes are on the table, whatever the request
  -- says: the cart and what the table ordered, less any other restaurant's.
  own AS (
    SELECT here.venue,
           ARRAY(SELECT c.id
                   FROM unnest(COALESCE(_cart_item_ids, '{}'::uuid[])) WITH ORDINALITY AS c(id, n)
                  WHERE NOT EXISTS (SELECT 1 FROM public.menu_items x
                                     WHERE x.id = c.id AND x.venue_id <> here.venue)
                  ORDER BY c.n) AS cart
      FROM here
  ),
  p AS (
    SELECT
      LEAST(GREATEST(COALESCE(_limit, 4), 1), 24) AS lim,
      own.venue,
      own.cart,
      CASE WHEN _placement IN ('cart', 'after_meal', 'item', 'tab') THEN _placement ELSE 'cart' END AS placement,
      CASE WHEN _language IN ('en', 'bs', 'ar') THEN _language ELSE 'en' END AS lang,
      public.reco_now() AS at,
      (public.reco_now() AT TIME ZONE 'Europe/Sarajevo')::time AS now_time,
      public.daypart_of(public.reco_now()) AS daypart,
      COALESCE(_session_id::text, 'anon') AS seed,
      public.guest_in_reco_holdout(_session_id) AS held_out,
      public.cart_diet(own.cart) AS diet,
      COALESCE(_exclude_allergens, '{}'::text[]) AS blocked_allergens,
      -- The wrapper adds 'alcohol' when the guest's diet filter excludes it.
      'alcohol' = ANY(COALESCE(_exclude_allergens, '{}'::text[])) AS no_alcohol,
      public.cart_has_drink(own.cart) AS has_drink,
      sc.ordered_item_ids,
      sc.served_item_ids,
      sc.minutes_since_served,
      -- The average line price includes what is in the cart right now, so the
      -- price check runs from the first round.
      (SELECT round((COALESCE(sc.running_total, 0) + COALESCE(sum(cm.price), 0))
                    / NULLIF(COALESCE(sc.line_count, 0) + count(cm.id), 0), 2)
         FROM public.menu_items cm
        WHERE cm.id = ANY(own.cart)) AS avg_line_price,
      -- Cart plus what the table already ordered: at the after-meal moment
      -- the cart is empty and this is all there is to pair against.
      (own.cart || ARRAY(SELECT t.id
                           FROM unnest(COALESCE(sc.ordered_item_ids, '{}'::uuid[])) WITH ORDINALITY AS t(id, n)
                          WHERE NOT EXISTS (SELECT 1 FROM public.menu_items x
                                             WHERE x.id = t.id AND x.venue_id <> own.venue)
                          ORDER BY t.n)) AS context,
      -- Portions on the table, this round and earlier ones: who is eating,
      -- and how many of them already have a drink.
      u.food_units,
      u.drink_units,
      -- Drinks for the grown-ups at the table: a child's meal is counted for
      -- the child's own drink (kids_qty), not for another lemonade.
      CASE WHEN GREATEST(COALESCE(sc.covers, 0), u.main_units) - u.kids_units >= 2
           THEN LEAST(GREATEST(GREATEST(COALESCE(sc.covers, 0), u.main_units) - u.kids_units - u.drink_units, 1), 6)
           ELSE 1 END AS table_qty,
      LEAST(GREATEST(u.kids_units, 1), 6) AS kids_qty,
      -- Cold drinks already on the table this visit (a combo comes with one),
      -- and how many people are eating: no second soft drink each.
      u.cold_units,
      GREATEST(COALESCE(sc.covers, 0), u.main_units, 1) AS people,
      -- The dish page asks about the dish first in the list; the rest is the cart.
      CASE WHEN _placement = 'item' AND cardinality(own.cart) > 1 THEN own.cart[1] END AS viewed,
      -- How often this restaurant's guests take a suggestion here at all: what
      -- a pair's own record is measured against.
      COALESCE((SELECT sp.alpha0 / NULLIF(sp.alpha0 + sp.beta0, 0)
                  FROM public.suggestion_priors sp
                 WHERE sp.recommended_item_id IS NULL
                   AND sp.venue_id = own.venue
                   AND sp.placement = CASE WHEN _placement IN ('cart', 'after_meal', 'item', 'tab') THEN _placement ELSE 'cart' END
                 LIMIT 1), 1.0 / 13) AS base_accept
    FROM public.session_context(_session_id) sc
    CROSS JOIN own
    CROSS JOIN LATERAL (
      SELECT COALESCE(sum(l.qty) FILTER (WHERE mi.meal_role = 'main'), 0)::int AS main_units,
             COALESCE(sum(l.qty) FILTER (WHERE mi.meal_role IN ('main', 'starter', 'side')
                                           OR (mi.meal_role IS NULL AND mi.station = 'kitchen')), 0)::int AS food_units,
             COALESCE(sum(l.qty) FILTER (WHERE public.role_is_drink(mi.meal_role)
                                           OR (mi.meal_role IS NULL AND mi.station = 'bar')), 0)::int AS drink_units,
             COALESCE(sum(l.qty) FILTER (WHERE mi.meal_role = 'cold_drink'
                                           OR (mi.meal_role IS NULL AND mi.station = 'bar')
                                           OR mi.name ~* '\mcombo\M'), 0)::int AS cold_units,
             COALESCE(sum(l.qty) FILTER (WHERE ks.name ~* '(kid|djec|dječ|dijete|child)'
                                           AND mi.name !~* '\mcombo\M'), 0)::int AS kids_units
        FROM (
          SELECT c.item_id, LEAST(GREATEST(COALESCE(c.qty, 1), 1), 10) AS qty
            FROM unnest(COALESCE(_cart_item_ids, '{}'::uuid[]), COALESCE(_cart_quantities, '{}'::int[]))
                 AS c(item_id, qty)
           WHERE c.item_id IS NOT NULL
          UNION ALL
          SELECT oi.menu_item_id, oi.quantity
            FROM public.order_items oi
            JOIN public.orders o ON o.id = oi.order_id
           WHERE _session_id IS NOT NULL
             AND o.table_session_id = _session_id
             AND o.status NOT IN ('cancelled', 'awaiting_payment', 'payment_failed')
        ) l
        JOIN public.menu_items mi ON mi.id = l.item_id
        LEFT JOIN public.subcategories ks ON ks.id = mi.subcategory_id
       WHERE mi.venue_id = own.venue
    ) u
  ),
  -- How overloaded the kitchen is right now. Biases AWAY from slow dishes
  -- under load; never hides anything.
  load AS (
    SELECT COALESCE(max(kl.load_factor), 0) AS factor
      FROM public.kitchen_load() kl
     WHERE kl.station = 'kitchen'
  ),
  -- What kind of thing each dish is (see reco_kind), and the kinds on the table.
  kinds AS (
    SELECT mi.id, public.reco_kind(mi.name, sub.name, mi.meal_role, mi.station) AS kind
      FROM public.menu_items mi
      LEFT JOIN public.subcategories sub ON sub.id = mi.subcategory_id
     WHERE mi.venue_id = (SELECT venue FROM here)
  ),
  context_kinds AS (
    SELECT DISTINCT k.kind FROM kinds k, p WHERE k.id = ANY(p.context)
  ),
  cart_subcategories AS (
    SELECT DISTINCT mi.subcategory_id
      FROM public.menu_items mi, p
     WHERE mi.id = ANY(p.cart)
  ),
  -- What a section rule may match: the cart, or on the running tab (where
  -- the cart is usually empty) what the table has ordered.
  rule_subcategories AS (
    SELECT DISTINCT mi.subcategory_id
      FROM public.menu_items mi, p
     WHERE mi.id = ANY(CASE WHEN p.placement = 'tab' THEN p.context ELSE p.cart END)
  ),
  curated AS (
    SELECT r.recommended_item_id AS item_id,
           -- house pairing source: a section rule names the cart dish it matched
           COALESCE(r.source_item_id,
                    (SELECT ci.id FROM public.menu_items ci
                      WHERE ci.id = ANY(CASE WHEN p.placement = 'tab' THEN p.context ELSE p.cart END)
                        AND ci.subcategory_id = r.source_subcategory_id
                      ORDER BY ci.price DESC, ci.id LIMIT 1)) AS source_item_id,
           r.recommendation_type AS rtype,
           max(r.priority)::numeric / 100 AS curated_score
      FROM public.menu_item_recommendations r, p
     WHERE r.enabled
       AND (r.language IS NULL OR r.language = p.lang)
       AND (r.start_time IS NULL OR p.now_time >= r.start_time)
       AND (r.end_time IS NULL OR p.now_time <= r.end_time)
       -- `alternative` is for the substitution path only.
       AND r.recommendation_type <> 'alternative'
       AND (
         (p.placement = 'after_meal' AND r.recommendation_type = 'after_meal')
         OR (p.placement <> 'after_meal' AND r.recommendation_type <> 'after_meal'
             AND (r.source_item_id = ANY(p.context)
                  OR r.source_subcategory_id IN (SELECT rs.subcategory_id FROM rule_subcategories rs)))
       )
     GROUP BY 1, 2, 3
  ),
  -- Visit-grain pairs, for the after-meal moment.
  observed_session AS (
    SELECT sa.item_b AS item_id,
           sa.item_a AS source_item_id,
           'after_meal'::text AS rtype,
           public.pair_strength(sa.eb05) AS observed_score
      FROM public.session_item_affinity sa, p
     WHERE sa.item_a = ANY(p.context)
       AND p.placement = 'after_meal'
       AND sa.eb05 > 1
  ),
  -- Order-grain pairs, for the cart and the dish page.
  observed AS (
    SELECT a.item_b AS item_id,
           a.item_a AS source_item_id,
           'frequently_bought_together'::text AS rtype,
           public.pair_strength(a.eb05) AS observed_score
      FROM public.menu_item_affinity a, p
     WHERE a.item_a = ANY(p.context)
       AND p.placement <> 'after_meal'
       AND a.eb05 > 1
  ),
  -- The sections on the table, each represented by its dearest dish there.
  context_sections AS (
    SELECT DISTINCT ON (mi.subcategory_id) mi.subcategory_id, mi.id AS source_item_id
      FROM public.menu_items mi, p
     WHERE mi.id = ANY(p.context) AND mi.subcategory_id IS NOT NULL
     ORDER BY mi.subcategory_id, mi.price DESC, mi.id
  ),
  /*
   * Section evidence, for dishes with no pair history of their own: a section
   * that goes with one on the table, offered as the dish that section sells
   * in this daypart. 0.6 × section strength × the dish's daypart share.
   */
  observed_family AS (
    SELECT sh.item_id,
           cs.source_item_id,
           'frequently_bought_together'::text AS rtype,
           round(0.6 * public.pair_strength(sf.eb05) * sh.share, 6) AS observed_score
      FROM context_sections cs
      JOIN public.subcategory_affinity sf ON sf.sub_a = cs.subcategory_id AND sf.eb05 > 1
      JOIN public.item_section_share sh ON sh.subcategory_id = sf.sub_b
      CROSS JOIN p
     WHERE p.placement <> 'after_meal'
       AND sh.daypart = p.daypart
       AND sh.share > 0
  ),
  /*
   * What tables taught it (reco_learned_pairs): dishes that tables with a
   * dish on this table — or, failing a record of its own, with a dish of
   * its section or kind — went on to order, beyond chance and from at least
   * three tables. Proposes and ranks; the gate below still decides.
   */
  learned AS (
    SELECT lp.item_id,
           lp.source_item_id,
           CASE WHEN p.placement = 'after_meal' THEN 'after_meal' ELSE 'frequently_bought_together' END::text AS rtype,
           lp.strength AS learned_score
      FROM p
      CROSS JOIN LATERAL public.reco_learned_pairs(p.context, p.at) lp
     WHERE lp.strength > 0
  ),
  -- Basket completion: a cart with food and no drink is a gap no pair table
  -- can see, because it is about something ABSENT.
  cart_kinds AS (
    SELECT DISTINCT k.kind FROM kinds k, p WHERE k.id = ANY(p.cart)
  ),
  /*
   * The fit graph also proposes, so that on the first night — no history,
   * nothing curated for this section — the right kind of thing is still on
   * the shortlist: a croissant for a fresh juice, a salad for a risotto.
   * It proposes and adds nothing to the score: fitting is the entry ticket,
   * not a merit, so margin and the price rule choose among these.
   */
  grammar AS (
    SELECT k.id AS item_id,
           (SELECT ci.id FROM public.menu_items ci JOIN kinds ck ON ck.id = ci.id
             WHERE ci.id = ANY(p.context) AND ck.kind = f.context_kind
             ORDER BY ci.price DESC, ci.id LIMIT 1) AS source_item_id,
           'goes_with'::text AS rtype,
           0::numeric AS observed_score
      FROM kinds k
      JOIN public.reco_fit f ON f.candidate_kind = k.kind
                             AND (f.venue_id IS NULL OR f.venue_id = (SELECT venue FROM here))
      CROSS JOIN p
     WHERE (p.placement = 'after_meal' AND f.context_kind = 'after_meal')
        OR (p.placement <> 'after_meal' AND f.context_kind IN (SELECT ck.kind FROM context_kinds ck))
  ),
  completion AS (
    SELECT mi.id AS item_id,
           -- The dish it is for, so the card can say "Goes with your burger".
           (SELECT ci.id FROM public.menu_items ci
             WHERE ci.id = ANY(p.context) AND ci.station = 'kitchen'
               AND ci.meal_role IS DISTINCT FROM 'dessert'
             ORDER BY ci.price DESC, ci.id LIMIT 1) AS source_item_id,
           'add_on'::text AS rtype,
           0.55::numeric AS observed_score
      FROM public.menu_items mi, p
     WHERE ((p.placement IN ('cart', 'item') AND cardinality(p.cart) > 0 AND NOT p.has_drink
             AND p.cold_units < p.people)
            -- On the running tab: the table ordered food and nothing to drink.
            OR (p.placement = 'tab' AND p.food_units > 0 AND p.drink_units = 0))
       AND mi.venue_id = p.venue
       AND public.role_is_drink(mi.meal_role)
  ),
  fallback AS (
    SELECT pop.menu_item_id AS item_id,
           NULL::uuid AS source_item_id,
           -- Labelled for what it is everywhere, the after-meal moment included.
           'popular'::text AS rtype,
           (0.08 + 0.02 * COALESCE(pop.relative, 1))::numeric AS observed_score
      FROM p
      CROSS JOIN LATERAL public.popular_items_for_daypart(p.daypart, 12, 45) pop
     WHERE NOT EXISTS (SELECT 1 FROM curated c WHERE c.item_id = pop.menu_item_id)
       AND NOT EXISTS (SELECT 1 FROM observed o WHERE o.item_id = pop.menu_item_id)
       AND NOT EXISTS (SELECT 1 FROM observed_family f WHERE f.item_id = pop.menu_item_id)
       AND NOT EXISTS (SELECT 1 FROM learned l WHERE l.item_id = pop.menu_item_id)
  ),
  candidates AS (
    SELECT item_id, source_item_id, rtype, curated_score, 0::numeric AS observed_score,
           0::numeric AS learned_score FROM curated
    UNION ALL
    SELECT item_id, source_item_id, rtype, 0::numeric, observed_score, 0::numeric FROM observed
    UNION ALL
    SELECT item_id, source_item_id, rtype, 0::numeric, observed_score, 0::numeric FROM observed_session
    UNION ALL
    SELECT item_id, source_item_id, rtype, 0::numeric, observed_score, 0::numeric FROM observed_family
    UNION ALL
    SELECT item_id, source_item_id, rtype, 0::numeric, 0::numeric, learned_score FROM learned
    UNION ALL
    SELECT item_id, source_item_id, rtype, 0::numeric, observed_score, 0::numeric FROM grammar
    UNION ALL
    SELECT item_id, source_item_id, rtype, 0::numeric, observed_score, 0::numeric FROM completion
    UNION ALL
    SELECT item_id, source_item_id, rtype, 0::numeric, observed_score, 0::numeric FROM fallback
  ),
  rolled AS (
    SELECT item_id,
           -- Say where it came from, strongest claim first: the owner's pairing
           -- or what tables taught it, whichever is stronger, then evidence,
           -- then completing the order, then the fit graph, then popularity.
           (array_agg(source_item_id ORDER BY GREATEST(curated_score, learned_score) DESC NULLS LAST,
                      CASE rtype WHEN 'frequently_bought_together' THEN 0 WHEN 'after_meal' THEN 0
                                 WHEN 'add_on' THEN 1 WHEN 'goes_with' THEN 2 ELSE 3 END,
                      observed_score DESC))[1] AS source_item_id,
           (array_agg(rtype ORDER BY GREATEST(curated_score, learned_score) DESC,
                      CASE rtype WHEN 'frequently_bought_together' THEN 0 WHEN 'after_meal' THEN 0
                                 WHEN 'add_on' THEN 1 WHEN 'goes_with' THEN 2 ELSE 3 END,
                      observed_score DESC))[1] AS rtype,
           max(curated_score)  AS curated_score,
           max(observed_score) AS observed_score,
           max(learned_score)  AS learned_score,
           -- The owner's own add-on for a dish on the table: chicken on the pasta.
           bool_or(rtype = 'add_on' AND curated_score > 0) AS curated_add_on
      FROM candidates
     GROUP BY item_id
  ),
  -- Everything that passed the guardrails, with what scoring needs.
  eligible AS (
    SELECT
      mi.id, mi.name, mi.name_bs, mi.name_ar, mi.price, mi.image_url, mi.dietary_tags,
      mi.margin_score,
      r.rtype, r.source_item_id, r.curated_score, r.observed_score, r.learned_score,
      -- Drinks for the table: one for each person still without one, when the
      -- whole order is in view (the cart before sending, or the running tab).
      CASE WHEN p.placement IN ('cart', 'tab') AND public.role_is_drink(mi.meal_role)
           THEN CASE WHEN EXISTS (SELECT 1 FROM public.menu_items si
                                    JOIN public.subcategories ss ON ss.id = si.subcategory_id
                                   WHERE si.id = r.source_item_id
                                     AND ss.name ~* '(kid|djec|dječ|dijete|child)')
                     THEN p.kids_qty ELSE p.table_qty END
           ELSE 1 END AS suggested_quantity,
      k.kind,
      public.reco_kind_group(k.kind) AS grp,
      -- How far exploration can lift this dish (the draw below is a share of it).
      s.w_explore * (30.0 / (30 + COALESCE(st.shown, 0))) AS explore_room,
      -- The dish page answers "what goes with THIS?": something that only goes
      -- with another dish in the cart is pushed down, not hidden.
      CASE
        WHEN p.viewed IS NULL OR r.source_item_id IS NOT DISTINCT FROM p.viewed THEN 0
        WHEN EXISTS (SELECT 1 FROM public.reco_fit vf JOIN kinds vk ON vk.id = p.viewed
                      WHERE vf.context_kind = vk.kind AND vf.candidate_kind = k.kind
                        AND (vf.venue_id IS NULL OR vf.venue_id = p.venue)) THEN 0
        ELSE 0.60
      END AS anchor_penalty,
      /*
       * How likely a guest is to take something at this price next to this
       * meal, before there is any record to say. Up to a comfortable share of
       * the table's average line (40% for a drink or side, 80% for a dessert
       * or starter, 100% for a main) price does not matter; beyond it the
       * chance falls with the square of the overshoot, so past that point a
       * dearer dish is expected to earn less, not more. It fades as the
       * pair's own record grows.
       */
      CASE WHEN p.avg_line_price IS NULL OR p.avg_line_price <= 0 OR mi.price <= 0 THEN 1
           ELSE LEAST(1, GREATEST(0.01, power(
                  (CASE WHEN mi.meal_role = 'main' THEN 1.0
                        WHEN mi.meal_role IN ('dessert', 'starter') THEN 0.8
                        ELSE 0.4 END) * p.avg_line_price / mi.price, 2)))
      END AS price_fit,
      COALESCE(st.shown, 0) AS shown,
      public.acceptance_for_ranking(mi.id, p.placement, r.source_item_id, p.daypart, p.seed) AS p_accept,
      -- Never zero for a missing food cost: menu_unit_margins() falls back
      -- to the role's default cost share.
      COALESCE(um.unit_cm, mi.price * (1 - public.default_cost_share(mi.meal_role)), 0) AS unit_cm,
      -- How much of the acceptance estimate is evidence (pair, then dish)
      -- rather than prior: 0 with no history, towards 1 with plenty.
      1 - ((pr.alpha0 + pr.beta0) / (pr.alpha0 + pr.beta0 + COALESCE(st.shown, 0)))
          * (50.0 / (50 + COALESCE(pr.item_shown, 0))) AS evidence,
      -- Sightings this visit that the guest passed on.
      (SELECT count(*)
         FROM public.recommendation_decisions d
         JOIN public.recommendation_impressions i ON i.decision_id = d.id
        WHERE _session_id IS NOT NULL
          AND d.session_id = _session_id
          AND d.chosen_item_id = mi.id
          AND NOT EXISTS (SELECT 1 FROM public.suggestion_conversions sc WHERE sc.decision_id = d.id)
      ) AS passed_over,
      -- Exploration: room for what has not been shown much, stable per visit.
      s.w_explore * (30.0 / (30 + COALESCE(st.shown, 0)))
                  * (('x' || substr(md5(p.seed || mi.id::text), 1, 8))::bit(32)::bigint % 1000)::numeric / 1000
        AS explore,
      -- Kitchen load: only once the kitchen is genuinely behind, only against
      -- slow dishes, never against the bar.
      CASE
        WHEN mi.station = 'bar' THEN 0
        WHEN (SELECT factor FROM load) <= 1 THEN 0
        ELSE LEAST(0.35,
               0.05 * ((SELECT factor FROM load) - 1)
                    * (COALESCE((SELECT e.minutes FROM public.item_prep_estimate(mi.id) e), 8) / 10.0))
      END AS load_penalty,
      -- Inferred diet: a nudge, not a wall; one salad must not hide the meat
      -- from the rest of the table. Never against the owner's own add-on for
      -- a dish on the table: at Vera Italia every pasta and risotto is
      -- vegetarian, so the inferred diet buried the chicken that exists to go
      -- on them. A guest's own filter (_require_tags) still removes it.
      CASE
        WHEN p.diet IS NULL THEN 0
        WHEN r.curated_add_on THEN 0
        WHEN p.diet = 'vegan' AND 'vegan' = ANY(mi.dietary_tags) THEN 0
        WHEN p.diet = 'vegetarian'
             AND ('vegetarian' = ANY(mi.dietary_tags) OR 'vegan' = ANY(mi.dietary_tags)) THEN 0
        ELSE 0.30
      END AS diet_penalty,
      -- Price proportionality. Something that goes WITH the meal should cost
      -- clearly less than the table's average line; another main may cost
      -- half as much again. Capped, so it pushes down rather than hides.
      CASE
        WHEN p.avg_line_price IS NULL OR p.avg_line_price <= 0 THEN 0
        -- A dessert or a starter is a course of its own, not a side: it may
        -- cost a little more than the average line before this bites.
        WHEN mi.meal_role IN ('dessert', 'starter') THEN
          CASE
            WHEN mi.price <= p.avg_line_price * 1.2 THEN 0
            ELSE LEAST(0.25, 0.30 * (mi.price / p.avg_line_price - 1.2))
          END
        WHEN mi.meal_role IS NOT NULL AND mi.meal_role <> 'main' THEN
          CASE
            WHEN mi.price <= p.avg_line_price * 0.75 THEN 0
            ELSE LEAST(0.25, 0.30 * (mi.price / p.avg_line_price - 0.75))
          END
        WHEN mi.price <= p.avg_line_price * 1.5 THEN 0
        ELSE LEAST(0.30, 0.15 * (mi.price / p.avg_line_price - 1.5))
      END AS price_penalty
    FROM rolled r
    JOIN public.menu_items mi ON mi.id = r.item_id
    JOIN kinds k ON k.id = mi.id
    CROSS JOIN p
    CROSS JOIN s
    CROSS JOIN LATERAL public.suggestion_prior(mi.id, p.placement) pr
    LEFT JOIN public.menu_unit_margins() um ON um.item_id = mi.id
    LEFT JOIN public.suggestion_stats st
           ON st.recommended_item_id = mi.id
          AND st.placement = p.placement
          AND st.source_item_id IS NOT DISTINCT FROM r.source_item_id
          AND st.daypart IS NULL
    WHERE s.enabled
      AND NOT p.held_out
      -- Never another restaurant's dish, whichever source proposed it.
      AND mi.venue_id = p.venue
      -- ---- Relevance first: a candidate is only scored if it belongs. ----
      -- Never volunteered: see reco_vetoed.
      AND NOT public.reco_vetoed(k.kind, mi.meal_role, r.curated_score > 0, p.at, p.placement)
      -- A reason to be here: the owner paired it, or the fit graph says it
      -- goes with something on the table (or after the meal). Popularity,
      -- co-occurrence and margin only ever rank what passed this.
      AND (r.curated_score > 0 OR EXISTS (
            SELECT 1 FROM public.reco_fit f
             WHERE f.candidate_kind = k.kind
               AND (f.venue_id IS NULL OR f.venue_id = p.venue)
               AND CASE WHEN p.placement = 'after_meal'
                        THEN f.context_kind = 'after_meal'
                        ELSE f.context_kind IN (SELECT ck.kind FROM context_kinds ck) END))
      -- Nothing that clashes with what is on the table, curated or not.
      AND NOT EXISTS (
            SELECT 1 FROM public.reco_clash c
             WHERE c.candidate_kind = k.kind
               AND (c.venue_id IS NULL OR c.venue_id = p.venue)
               AND c.context_kind IN (SELECT ck.kind FROM context_kinds ck))
      -- No second of a kind already in this round: we can add, not swap, so
      -- an "upgrade" to truffle fries next to regular fries is a second side.
      AND (p.placement = 'after_meal' OR k.kind NOT IN (SELECT kk.kind FROM cart_kinds kk))
      -- ---- Guardrails. Scoring cannot override any of these. ----
      AND public.menu_item_orderable(mi, p.now_time)
      -- Never re-suggest what is in the cart right now; beyond that, ask the
      -- role (a second coffee is ordinary café behaviour).
      AND NOT (mi.id = ANY(p.cart))
      -- No second soft drink each: once the table has as many cold drinks as
      -- people (this round or an earlier one), none is offered with the food.
      AND NOT (p.placement IN ('cart', 'item') AND mi.meal_role = 'cold_drink' AND p.cold_units >= p.people)
      AND NOT public.repeat_blocked(mi.id, _session_id)
      AND (r.rtype IN ('upgrade_to', 'add_on', 'after_meal')
           OR mi.subcategory_id NOT IN (SELECT cs.subcategory_id FROM cart_subcategories cs))
      -- Retired: shown fairly often, and even an optimistic reading of the
      -- record is below the floor.
      AND NOT (
        COALESCE(st.shown, 0) >= s.retire_after
        AND public.acceptance_retired(COALESCE(st.accepted, 0), COALESCE(st.shown, 0),
                                      pr.alpha0, pr.beta0, s.min_acceptance)
      )
      -- Never suggest around an allergen the guest has filtered out.
      AND NOT (mi.allergens && p.blocked_allergens)
      -- Coursing and the alcohol rule. See reco_role_fits.
      AND public.reco_role_fits(
            mi.meal_role,
            p.placement,
            CASE WHEN EXISTS (SELECT 1 FROM observed ob WHERE ob.item_id = mi.id)
                   OR EXISTS (SELECT 1 FROM observed_session obs WHERE obs.item_id = mi.id)
                   OR EXISTS (SELECT 1 FROM observed_family obf WHERE obf.item_id = mi.id)
                   OR EXISTS (SELECT 1 FROM learned lr WHERE lr.item_id = mi.id)
                 THEN 'observed' ELSE r.rtype END,
            r.curated_score > 0,
            p.cart,
            _session_id,
            p.at,
            p.no_alcohol)
      -- A kids' meal is for a child the menu cannot see: only when curated.
      AND (r.curated_score > 0 OR NOT EXISTS (
            SELECT 1 FROM public.subcategories ks
             WHERE ks.id = mi.subcategory_id
               AND ks.name ~* '(kid|djec|dječ|dijete|child)'))
  ),
  valued AS (
    SELECT e.*,
           e.p_accept * e.unit_cm * (1 - (1 - e.price_fit) * (1 - e.evidence)) AS expected_value
      FROM eligible e
  ),
  scored AS (
    SELECT v.*,
      -- Curated priority and observed strength stand in for "guests will take
      -- this". Once a pair has a record of its own they give way to it, down
      -- to a fifth, and measured expected profit decides. What tables taught
      -- it ranks on the curated scale: the stronger of the two counts.
      ( (1 - v.evidence) * (s.w_curated * GREATEST(v.curated_score, v.learned_score)
                            + s.w_observed * v.observed_score)
      -- ...and what its own record says, on the scale of a house priority:
      -- taken as often as suggestions are taken here = 0.5, at most 0.6 (a
      -- good house priority); beyond that, what it earns (below, with how
      -- often it is taken) decides. A pair guests keep taking rises; one they
      -- ignore falls; exploration can still give a new dish its turn.
      + v.evidence * s.w_curated * LEAST(0.6, 0.5 * v.p_accept / NULLIF(p.base_accept, 0))
      -- Expected profit: a light hand while it rests on assumptions, the
      -- full weight once the pair has a record.
      + s.w_value * (0.3 + 0.7 * v.evidence)
                  * COALESCE(v.expected_value / NULLIF(max(v.expected_value) OVER (), 0), 0)
      + (0.10 * COALESCE(v.margin_score, 0)::numeric / 100 - 0.05)
      + v.explore
      - v.load_penalty
      - v.diet_penalty
      - v.price_penalty
      - v.anchor_penalty
      - 0.15 * v.passed_over
      ) AS score
    FROM valued v
    CROSS JOIN s
    CROSS JOIN p
  ),
  /*
   * One of each before two of anything: the best stays first; after it, the
   * best of each other group with a pairing behind it (the house's, what
   * tables taught, or co-occurrence) comes before a second of any group, or a
   * filler with no pairing behind it, unless those lead by more than 0.15.
   * Burger: a drink, then fries. Pasta: a drink, then the salad. A dessert:
   * an espresso, a cappuccino — not a bottle of water for variety's sake.
   */
  diversified AS (
    SELECT sc.*,
           row_number() OVER (ORDER BY sc.score DESC, sc.price ASC, sc.id) AS overall,
           row_number() OVER (PARTITION BY sc.grp ORDER BY sc.score DESC, sc.price ASC, sc.id) AS grp_rank
      FROM scored sc
  )
  SELECT d.id, d.name, d.name_bs, d.name_ar, d.price, d.image_url, d.dietary_tags,
         d.rtype AS recommendation_type,
         d.rtype AS reason,
         d.source_item_id,
         d.suggested_quantity,
         round(d.score, 6) AS score,
         round(d.explore, 6) AS explore,
         round(d.explore_room, 6) AS explore_room,
         d.grp,
         d.kind,
         round(d.curated_score, 4) AS curated_score,
         round(d.learned_score, 4) AS learned_score,
         round(d.observed_score, 4) AS observed_score,
         round(d.evidence, 4) AS evidence,
         round(d.p_accept, 4) AS p_accept,
         (row_number() OVER (ORDER BY CASE WHEN d.overall = 1 THEN 1e9
                                           WHEN d.grp_rank = 1
                                                AND (d.curated_score > 0 OR d.learned_score > 0
                                                     OR d.rtype IN ('frequently_bought_together', 'after_meal'))
                                             THEN d.score
                                           ELSE d.score - 0.15 END DESC,
                                      d.score DESC, d.price ASC, d.id))::int AS ord
    FROM diversified d
   ORDER BY ord
   LIMIT (SELECT lim FROM p);
$function$;

REVOKE ALL ON FUNCTION public.reco_rank_scored_v3(uuid[], text, text, int, uuid, text[], int[]) FROM PUBLIC, anon;

-- ---------------------------------------------------------------------
-- 5. The v4 ranker: the same, with a posterior draw for P(taken)
-- ---------------------------------------------------------------------

-- Copied from 20261031120000_reco_quality.sql; every change is marked v4.
CREATE OR REPLACE FUNCTION public.reco_rank_scored_v4(_cart_item_ids uuid[] DEFAULT '{}'::uuid[], _placement text DEFAULT 'cart'::text, _language text DEFAULT 'en'::text, _limit integer DEFAULT 4, _session_id uuid DEFAULT NULL::uuid, _exclude_allergens text[] DEFAULT '{}'::text[], _cart_quantities integer[] DEFAULT NULL::integer[])
 RETURNS TABLE(id uuid, name text, name_bs text, name_ar text, price numeric, image_url text, dietary_tags text[], recommendation_type text, reason text, source_item_id uuid, suggested_quantity integer, score numeric, explore numeric, explore_room numeric, grp text, kind text, curated_score numeric, learned_score numeric, observed_score numeric, evidence numeric, p_accept numeric, ord integer, p_mean numeric, p_sd numeric, p_k numeric, base_accept numeric, coef_cur numeric, coef_val numeric, cm_factor numeric, score_fixed numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH here AS (
    SELECT public.current_venue() AS venue
  ),
  s AS (
    SELECT
      COALESCE(recommendations_enabled, true) AS enabled,
      COALESCE(reco_weight_curated, 40)::numeric  / 100 AS w_curated,
      COALESCE(reco_weight_observed, 25)::numeric / 100 AS w_observed,
      (COALESCE(reco_weight_learned, 25) + COALESCE(reco_weight_margin, 10))::numeric / 100 AS w_value,
      COALESCE(reco_exploration, 15)::numeric     / 100 AS w_explore,
      COALESCE(reco_min_acceptance, 0.03)               AS min_acceptance,
      COALESCE(reco_retire_after_impressions, 60)       AS retire_after
    FROM public.restaurant_settings WHERE venue_id = (SELECT venue FROM here)
  ),
  -- Only this restaurant's dishes are on the table, whatever the request
  -- says: the cart and what the table ordered, less any other restaurant's.
  own AS (
    SELECT here.venue,
           ARRAY(SELECT c.id
                   FROM unnest(COALESCE(_cart_item_ids, '{}'::uuid[])) WITH ORDINALITY AS c(id, n)
                  WHERE NOT EXISTS (SELECT 1 FROM public.menu_items x
                                     WHERE x.id = c.id AND x.venue_id <> here.venue)
                  ORDER BY c.n) AS cart
      FROM here
  ),
  p AS (
    SELECT
      LEAST(GREATEST(COALESCE(_limit, 4), 1), 24) AS lim,
      own.venue,
      own.cart,
      CASE WHEN _placement IN ('cart', 'after_meal', 'item', 'tab') THEN _placement ELSE 'cart' END AS placement,
      CASE WHEN _language IN ('en', 'bs', 'ar') THEN _language ELSE 'en' END AS lang,
      public.reco_now() AS at,
      (public.reco_now() AT TIME ZONE 'Europe/Sarajevo')::time AS now_time,
      public.daypart_of(public.reco_now()) AS daypart,
      COALESCE(_session_id::text, 'anon') AS seed,
      public.guest_in_reco_holdout(_session_id) AS held_out,
      public.cart_diet(own.cart) AS diet,
      COALESCE(_exclude_allergens, '{}'::text[]) AS blocked_allergens,
      -- The wrapper adds 'alcohol' when the guest's diet filter excludes it.
      'alcohol' = ANY(COALESCE(_exclude_allergens, '{}'::text[])) AS no_alcohol,
      public.cart_has_drink(own.cart) AS has_drink,
      sc.ordered_item_ids,
      sc.served_item_ids,
      sc.minutes_since_served,
      -- The average line price includes what is in the cart right now, so the
      -- price check runs from the first round.
      (SELECT round((COALESCE(sc.running_total, 0) + COALESCE(sum(cm.price), 0))
                    / NULLIF(COALESCE(sc.line_count, 0) + count(cm.id), 0), 2)
         FROM public.menu_items cm
        WHERE cm.id = ANY(own.cart)) AS avg_line_price,
      -- Cart plus what the table already ordered: at the after-meal moment
      -- the cart is empty and this is all there is to pair against.
      (own.cart || ARRAY(SELECT t.id
                           FROM unnest(COALESCE(sc.ordered_item_ids, '{}'::uuid[])) WITH ORDINALITY AS t(id, n)
                          WHERE NOT EXISTS (SELECT 1 FROM public.menu_items x
                                             WHERE x.id = t.id AND x.venue_id <> own.venue)
                          ORDER BY t.n)) AS context,
      -- Portions on the table, this round and earlier ones: who is eating,
      -- and how many of them already have a drink.
      u.food_units,
      u.drink_units,
      -- Drinks for the grown-ups at the table: a child's meal is counted for
      -- the child's own drink (kids_qty), not for another lemonade.
      CASE WHEN GREATEST(COALESCE(sc.covers, 0), u.main_units) - u.kids_units >= 2
           THEN LEAST(GREATEST(GREATEST(COALESCE(sc.covers, 0), u.main_units) - u.kids_units - u.drink_units, 1), 6)
           ELSE 1 END AS table_qty,
      LEAST(GREATEST(u.kids_units, 1), 6) AS kids_qty,
      -- Cold drinks already on the table this visit (a combo comes with one),
      -- and how many people are eating: no second soft drink each.
      u.cold_units,
      GREATEST(COALESCE(sc.covers, 0), u.main_units, 1) AS people,
      -- The dish page asks about the dish first in the list; the rest is the cart.
      CASE WHEN _placement = 'item' AND cardinality(own.cart) > 1 THEN own.cart[1] END AS viewed,
      -- How often this restaurant's guests take a suggestion here at all: what
      -- a pair's own record is measured against.
      COALESCE((SELECT sp.alpha0 / NULLIF(sp.alpha0 + sp.beta0, 0)
                  FROM public.suggestion_priors sp
                 WHERE sp.recommended_item_id IS NULL
                   AND sp.venue_id = own.venue
                   AND sp.placement = CASE WHEN _placement IN ('cart', 'after_meal', 'item', 'tab') THEN _placement ELSE 'cart' END
                 LIMIT 1), 1.0 / 13) AS base_accept
    FROM public.session_context(_session_id) sc
    CROSS JOIN own
    CROSS JOIN LATERAL (
      SELECT COALESCE(sum(l.qty) FILTER (WHERE mi.meal_role = 'main'), 0)::int AS main_units,
             COALESCE(sum(l.qty) FILTER (WHERE mi.meal_role IN ('main', 'starter', 'side')
                                           OR (mi.meal_role IS NULL AND mi.station = 'kitchen')), 0)::int AS food_units,
             COALESCE(sum(l.qty) FILTER (WHERE public.role_is_drink(mi.meal_role)
                                           OR (mi.meal_role IS NULL AND mi.station = 'bar')), 0)::int AS drink_units,
             COALESCE(sum(l.qty) FILTER (WHERE mi.meal_role = 'cold_drink'
                                           OR (mi.meal_role IS NULL AND mi.station = 'bar')
                                           OR mi.name ~* '\mcombo\M'), 0)::int AS cold_units,
             COALESCE(sum(l.qty) FILTER (WHERE ks.name ~* '(kid|djec|dječ|dijete|child)'
                                           AND mi.name !~* '\mcombo\M'), 0)::int AS kids_units
        FROM (
          SELECT c.item_id, LEAST(GREATEST(COALESCE(c.qty, 1), 1), 10) AS qty
            FROM unnest(COALESCE(_cart_item_ids, '{}'::uuid[]), COALESCE(_cart_quantities, '{}'::int[]))
                 AS c(item_id, qty)
           WHERE c.item_id IS NOT NULL
          UNION ALL
          SELECT oi.menu_item_id, oi.quantity
            FROM public.order_items oi
            JOIN public.orders o ON o.id = oi.order_id
           WHERE _session_id IS NOT NULL
             AND o.table_session_id = _session_id
             AND o.status NOT IN ('cancelled', 'awaiting_payment', 'payment_failed')
        ) l
        JOIN public.menu_items mi ON mi.id = l.item_id
        LEFT JOIN public.subcategories ks ON ks.id = mi.subcategory_id
       WHERE mi.venue_id = own.venue
    ) u
  ),
  -- How overloaded the kitchen is right now. Biases AWAY from slow dishes
  -- under load; never hides anything.
  load AS (
    SELECT COALESCE(max(kl.load_factor), 0) AS factor
      FROM public.kitchen_load() kl
     WHERE kl.station = 'kitchen'
  ),
  -- What kind of thing each dish is (see reco_kind), and the kinds on the table.
  kinds AS (
    SELECT mi.id, public.reco_kind(mi.name, sub.name, mi.meal_role, mi.station) AS kind
      FROM public.menu_items mi
      LEFT JOIN public.subcategories sub ON sub.id = mi.subcategory_id
     WHERE mi.venue_id = (SELECT venue FROM here)
  ),
  context_kinds AS (
    SELECT DISTINCT k.kind FROM kinds k, p WHERE k.id = ANY(p.context)
  ),
  cart_subcategories AS (
    SELECT DISTINCT mi.subcategory_id
      FROM public.menu_items mi, p
     WHERE mi.id = ANY(p.cart)
  ),
  -- What a section rule may match: the cart, or on the running tab (where
  -- the cart is usually empty) what the table has ordered.
  rule_subcategories AS (
    SELECT DISTINCT mi.subcategory_id
      FROM public.menu_items mi, p
     WHERE mi.id = ANY(CASE WHEN p.placement = 'tab' THEN p.context ELSE p.cart END)
  ),
  curated AS (
    SELECT r.recommended_item_id AS item_id,
           -- house pairing source: a section rule names the cart dish it matched
           COALESCE(r.source_item_id,
                    (SELECT ci.id FROM public.menu_items ci
                      WHERE ci.id = ANY(CASE WHEN p.placement = 'tab' THEN p.context ELSE p.cart END)
                        AND ci.subcategory_id = r.source_subcategory_id
                      ORDER BY ci.price DESC, ci.id LIMIT 1)) AS source_item_id,
           r.recommendation_type AS rtype,
           max(r.priority)::numeric / 100 AS curated_score
      FROM public.menu_item_recommendations r, p
     WHERE r.enabled
       AND (r.language IS NULL OR r.language = p.lang)
       AND (r.start_time IS NULL OR p.now_time >= r.start_time)
       AND (r.end_time IS NULL OR p.now_time <= r.end_time)
       -- `alternative` is for the substitution path only.
       AND r.recommendation_type <> 'alternative'
       AND (
         (p.placement = 'after_meal' AND r.recommendation_type = 'after_meal')
         OR (p.placement <> 'after_meal' AND r.recommendation_type <> 'after_meal'
             AND (r.source_item_id = ANY(p.context)
                  OR r.source_subcategory_id IN (SELECT rs.subcategory_id FROM rule_subcategories rs)))
       )
     GROUP BY 1, 2, 3
  ),
  -- Visit-grain pairs, for the after-meal moment.
  observed_session AS (
    SELECT sa.item_b AS item_id,
           sa.item_a AS source_item_id,
           'after_meal'::text AS rtype,
           public.pair_strength(sa.eb05) AS observed_score
      FROM public.session_item_affinity sa, p
     WHERE sa.item_a = ANY(p.context)
       AND p.placement = 'after_meal'
       AND sa.eb05 > 1
  ),
  -- Order-grain pairs, for the cart and the dish page.
  observed AS (
    SELECT a.item_b AS item_id,
           a.item_a AS source_item_id,
           'frequently_bought_together'::text AS rtype,
           public.pair_strength(a.eb05) AS observed_score
      FROM public.menu_item_affinity a, p
     WHERE a.item_a = ANY(p.context)
       AND p.placement <> 'after_meal'
       AND a.eb05 > 1
  ),
  -- The sections on the table, each represented by its dearest dish there.
  context_sections AS (
    SELECT DISTINCT ON (mi.subcategory_id) mi.subcategory_id, mi.id AS source_item_id
      FROM public.menu_items mi, p
     WHERE mi.id = ANY(p.context) AND mi.subcategory_id IS NOT NULL
     ORDER BY mi.subcategory_id, mi.price DESC, mi.id
  ),
  /*
   * Section evidence, for dishes with no pair history of their own: a section
   * that goes with one on the table, offered as the dish that section sells
   * in this daypart. 0.6 × section strength × the dish's daypart share.
   */
  observed_family AS (
    SELECT sh.item_id,
           cs.source_item_id,
           'frequently_bought_together'::text AS rtype,
           round(0.6 * public.pair_strength(sf.eb05) * sh.share, 6) AS observed_score
      FROM context_sections cs
      JOIN public.subcategory_affinity sf ON sf.sub_a = cs.subcategory_id AND sf.eb05 > 1
      JOIN public.item_section_share sh ON sh.subcategory_id = sf.sub_b
      CROSS JOIN p
     WHERE p.placement <> 'after_meal'
       AND sh.daypart = p.daypart
       AND sh.share > 0
  ),
  /*
   * What tables taught it (reco_learned_pairs): dishes that tables with a
   * dish on this table — or, failing a record of its own, with a dish of
   * its section or kind — went on to order, beyond chance and from at least
   * three tables. Proposes and ranks; the gate below still decides.
   */
  learned AS (
    SELECT lp.item_id,
           lp.source_item_id,
           CASE WHEN p.placement = 'after_meal' THEN 'after_meal' ELSE 'frequently_bought_together' END::text AS rtype,
           lp.strength AS learned_score
      FROM p
      CROSS JOIN LATERAL public.reco_learned_pairs(p.context, p.at) lp
     WHERE lp.strength > 0
  ),
  -- Basket completion: a cart with food and no drink is a gap no pair table
  -- can see, because it is about something ABSENT.
  cart_kinds AS (
    SELECT DISTINCT k.kind FROM kinds k, p WHERE k.id = ANY(p.cart)
  ),
  /*
   * The fit graph also proposes, so that on the first night — no history,
   * nothing curated for this section — the right kind of thing is still on
   * the shortlist: a croissant for a fresh juice, a salad for a risotto.
   * It proposes and adds nothing to the score: fitting is the entry ticket,
   * not a merit, so margin and the price rule choose among these.
   */
  grammar AS (
    SELECT k.id AS item_id,
           (SELECT ci.id FROM public.menu_items ci JOIN kinds ck ON ck.id = ci.id
             WHERE ci.id = ANY(p.context) AND ck.kind = f.context_kind
             ORDER BY ci.price DESC, ci.id LIMIT 1) AS source_item_id,
           'goes_with'::text AS rtype,
           0::numeric AS observed_score
      FROM kinds k
      JOIN public.reco_fit f ON f.candidate_kind = k.kind
                             AND (f.venue_id IS NULL OR f.venue_id = (SELECT venue FROM here))
      CROSS JOIN p
     WHERE (p.placement = 'after_meal' AND f.context_kind = 'after_meal')
        OR (p.placement <> 'after_meal' AND f.context_kind IN (SELECT ck.kind FROM context_kinds ck))
  ),
  completion AS (
    SELECT mi.id AS item_id,
           -- The dish it is for, so the card can say "Goes with your burger".
           (SELECT ci.id FROM public.menu_items ci
             WHERE ci.id = ANY(p.context) AND ci.station = 'kitchen'
               AND ci.meal_role IS DISTINCT FROM 'dessert'
             ORDER BY ci.price DESC, ci.id LIMIT 1) AS source_item_id,
           'add_on'::text AS rtype,
           0.55::numeric AS observed_score
      FROM public.menu_items mi, p
     WHERE ((p.placement IN ('cart', 'item') AND cardinality(p.cart) > 0 AND NOT p.has_drink
             AND p.cold_units < p.people)
            -- On the running tab: the table ordered food and nothing to drink.
            OR (p.placement = 'tab' AND p.food_units > 0 AND p.drink_units = 0))
       AND mi.venue_id = p.venue
       AND public.role_is_drink(mi.meal_role)
  ),
  fallback AS (
    SELECT pop.menu_item_id AS item_id,
           NULL::uuid AS source_item_id,
           -- Labelled for what it is everywhere, the after-meal moment included.
           'popular'::text AS rtype,
           (0.08 + 0.02 * COALESCE(pop.relative, 1))::numeric AS observed_score
      FROM p
      CROSS JOIN LATERAL public.popular_items_for_daypart(p.daypart, 12, 45) pop
     WHERE NOT EXISTS (SELECT 1 FROM curated c WHERE c.item_id = pop.menu_item_id)
       AND NOT EXISTS (SELECT 1 FROM observed o WHERE o.item_id = pop.menu_item_id)
       AND NOT EXISTS (SELECT 1 FROM observed_family f WHERE f.item_id = pop.menu_item_id)
       AND NOT EXISTS (SELECT 1 FROM learned l WHERE l.item_id = pop.menu_item_id)
  ),
  candidates AS (
    SELECT item_id, source_item_id, rtype, curated_score, 0::numeric AS observed_score,
           0::numeric AS learned_score FROM curated
    UNION ALL
    SELECT item_id, source_item_id, rtype, 0::numeric, observed_score, 0::numeric FROM observed
    UNION ALL
    SELECT item_id, source_item_id, rtype, 0::numeric, observed_score, 0::numeric FROM observed_session
    UNION ALL
    SELECT item_id, source_item_id, rtype, 0::numeric, observed_score, 0::numeric FROM observed_family
    UNION ALL
    SELECT item_id, source_item_id, rtype, 0::numeric, 0::numeric, learned_score FROM learned
    UNION ALL
    SELECT item_id, source_item_id, rtype, 0::numeric, observed_score, 0::numeric FROM grammar
    UNION ALL
    SELECT item_id, source_item_id, rtype, 0::numeric, observed_score, 0::numeric FROM completion
    UNION ALL
    SELECT item_id, source_item_id, rtype, 0::numeric, observed_score, 0::numeric FROM fallback
  ),
  rolled AS (
    SELECT item_id,
           -- Say where it came from, strongest claim first: the owner's pairing
           -- or what tables taught it, whichever is stronger, then evidence,
           -- then completing the order, then the fit graph, then popularity.
           (array_agg(source_item_id ORDER BY GREATEST(curated_score, learned_score) DESC NULLS LAST,
                      CASE rtype WHEN 'frequently_bought_together' THEN 0 WHEN 'after_meal' THEN 0
                                 WHEN 'add_on' THEN 1 WHEN 'goes_with' THEN 2 ELSE 3 END,
                      observed_score DESC))[1] AS source_item_id,
           (array_agg(rtype ORDER BY GREATEST(curated_score, learned_score) DESC,
                      CASE rtype WHEN 'frequently_bought_together' THEN 0 WHEN 'after_meal' THEN 0
                                 WHEN 'add_on' THEN 1 WHEN 'goes_with' THEN 2 ELSE 3 END,
                      observed_score DESC))[1] AS rtype,
           max(curated_score)  AS curated_score,
           max(observed_score) AS observed_score,
           max(learned_score)  AS learned_score,
           -- The owner's own add-on for a dish on the table: chicken on the pasta.
           bool_or(rtype = 'add_on' AND curated_score > 0) AS curated_add_on
      FROM candidates
     GROUP BY item_id
  ),
  -- Everything that passed the guardrails, with what scoring needs.
  eligible AS (
    SELECT
      mi.id, mi.name, mi.name_bs, mi.name_ar, mi.price, mi.image_url, mi.dietary_tags,
      mi.margin_score,
      r.rtype, r.source_item_id, r.curated_score, r.observed_score, r.learned_score,
      -- Drinks for the table: one for each person still without one, when the
      -- whole order is in view (the cart before sending, or the running tab).
      CASE WHEN p.placement IN ('cart', 'tab') AND public.role_is_drink(mi.meal_role)
           THEN CASE WHEN EXISTS (SELECT 1 FROM public.menu_items si
                                    JOIN public.subcategories ss ON ss.id = si.subcategory_id
                                   WHERE si.id = r.source_item_id
                                     AND ss.name ~* '(kid|djec|dječ|dijete|child)')
                     THEN p.kids_qty ELSE p.table_qty END
           ELSE 1 END AS suggested_quantity,
      k.kind,
      public.reco_kind_group(k.kind) AS grp,
      -- How far exploration can lift this dish (the draw below is a share of it).
      -- v4: no blind novelty bonus; the posterior draw above explores.
      0::numeric AS explore_room,
      -- The dish page answers "what goes with THIS?": something that only goes
      -- with another dish in the cart is pushed down, not hidden.
      CASE
        WHEN p.viewed IS NULL OR r.source_item_id IS NOT DISTINCT FROM p.viewed THEN 0
        WHEN EXISTS (SELECT 1 FROM public.reco_fit vf JOIN kinds vk ON vk.id = p.viewed
                      WHERE vf.context_kind = vk.kind AND vf.candidate_kind = k.kind
                        AND (vf.venue_id IS NULL OR vf.venue_id = p.venue)) THEN 0
        ELSE 0.60
      END AS anchor_penalty,
      /*
       * How likely a guest is to take something at this price next to this
       * meal, before there is any record to say. Up to a comfortable share of
       * the table's average line (40% for a drink or side, 80% for a dessert
       * or starter, 100% for a main) price does not matter; beyond it the
       * chance falls with the square of the overshoot, so past that point a
       * dearer dish is expected to earn less, not more. It fades as the
       * pair's own record grows.
       */
      CASE WHEN p.avg_line_price IS NULL OR p.avg_line_price <= 0 OR mi.price <= 0 THEN 1
           ELSE LEAST(1, GREATEST(0.01, power(
                  (CASE WHEN mi.meal_role = 'main' THEN 1.0
                        WHEN mi.meal_role IN ('dessert', 'starter') THEN 0.8
                        ELSE 0.4 END) * p.avg_line_price / mi.price, 2)))
      END AS price_fit,
      COALESCE(st.shown, 0) AS shown,
      -- v4: a draw from the pair's posterior in this guest's language (reco_posterior_v4),
      -- as far from its mean as the exploration dial allows (15 = a full Thompson draw,
      -- 0 = the mean). Stable for the visit: the seed is the table session.
      LEAST(1, GREATEST(0.001, pv.mean + (s.w_explore / 0.15) * pv.z * pv.sd)) AS p_accept,
      pv.mean AS p_mean,
      pv.sd AS p_sd,
      s.w_explore / 0.15 AS p_k,
      -- Never zero for a missing food cost: menu_unit_margins() falls back
      -- to the role's default cost share.
      COALESCE(um.unit_cm, mi.price * (1 - public.default_cost_share(mi.meal_role)), 0) AS unit_cm,
      -- How much of the acceptance estimate is evidence (pair, then dish)
      -- rather than prior: 0 with no history, towards 1 with plenty.
      1 - ((pr.alpha0 + pr.beta0) / (pr.alpha0 + pr.beta0 + COALESCE(st.shown, 0)))
          * (50.0 / (50 + COALESCE(pr.item_shown, 0))) AS evidence,
      -- Sightings this visit that the guest passed on.
      (SELECT count(*)
         FROM public.recommendation_decisions d
         JOIN public.recommendation_impressions i ON i.decision_id = d.id
        WHERE _session_id IS NOT NULL
          AND d.session_id = _session_id
          AND d.chosen_item_id = mi.id
          AND NOT EXISTS (SELECT 1 FROM public.suggestion_conversions sc WHERE sc.decision_id = d.id)
      ) AS passed_over,
      0::numeric AS explore,
      -- Kitchen load: only once the kitchen is genuinely behind, only against
      -- slow dishes, never against the bar.
      CASE
        WHEN mi.station = 'bar' THEN 0
        WHEN (SELECT factor FROM load) <= 1 THEN 0
        ELSE LEAST(0.35,
               0.05 * ((SELECT factor FROM load) - 1)
                    * (COALESCE((SELECT e.minutes FROM public.item_prep_estimate(mi.id) e), 8) / 10.0))
      END AS load_penalty,
      -- Inferred diet: a nudge, not a wall; one salad must not hide the meat
      -- from the rest of the table. Never against the owner's own add-on for
      -- a dish on the table: at Vera Italia every pasta and risotto is
      -- vegetarian, so the inferred diet buried the chicken that exists to go
      -- on them. A guest's own filter (_require_tags) still removes it.
      CASE
        WHEN p.diet IS NULL THEN 0
        WHEN r.curated_add_on THEN 0
        WHEN p.diet = 'vegan' AND 'vegan' = ANY(mi.dietary_tags) THEN 0
        WHEN p.diet = 'vegetarian'
             AND ('vegetarian' = ANY(mi.dietary_tags) OR 'vegan' = ANY(mi.dietary_tags)) THEN 0
        ELSE 0.30
      END AS diet_penalty,
      -- Price proportionality. Something that goes WITH the meal should cost
      -- clearly less than the table's average line; another main may cost
      -- half as much again. Capped, so it pushes down rather than hides.
      CASE
        WHEN p.avg_line_price IS NULL OR p.avg_line_price <= 0 THEN 0
        -- A dessert or a starter is a course of its own, not a side: it may
        -- cost a little more than the average line before this bites.
        WHEN mi.meal_role IN ('dessert', 'starter') THEN
          CASE
            WHEN mi.price <= p.avg_line_price * 1.2 THEN 0
            ELSE LEAST(0.25, 0.30 * (mi.price / p.avg_line_price - 1.2))
          END
        WHEN mi.meal_role IS NOT NULL AND mi.meal_role <> 'main' THEN
          CASE
            WHEN mi.price <= p.avg_line_price * 0.75 THEN 0
            ELSE LEAST(0.25, 0.30 * (mi.price / p.avg_line_price - 0.75))
          END
        WHEN mi.price <= p.avg_line_price * 1.5 THEN 0
        ELSE LEAST(0.30, 0.15 * (mi.price / p.avg_line_price - 1.5))
      END AS price_penalty
    FROM rolled r
    JOIN public.menu_items mi ON mi.id = r.item_id
    JOIN kinds k ON k.id = mi.id
    CROSS JOIN p
    CROSS JOIN s
    CROSS JOIN LATERAL public.suggestion_prior(mi.id, p.placement) pr
    CROSS JOIN LATERAL public.reco_posterior_v4(mi.id, p.placement, r.source_item_id, p.daypart, p.lang, p.seed) pv
    LEFT JOIN public.menu_unit_margins() um ON um.item_id = mi.id
    LEFT JOIN public.suggestion_stats st
           ON st.recommended_item_id = mi.id
          AND st.placement = p.placement
          AND st.source_item_id IS NOT DISTINCT FROM r.source_item_id
          AND st.daypart IS NULL
    WHERE s.enabled
      AND NOT p.held_out
      -- Never another restaurant's dish, whichever source proposed it.
      AND mi.venue_id = p.venue
      -- ---- Relevance first: a candidate is only scored if it belongs. ----
      -- Never volunteered: see reco_vetoed.
      AND NOT public.reco_vetoed(k.kind, mi.meal_role, r.curated_score > 0, p.at, p.placement)
      -- A reason to be here: the owner paired it, or the fit graph says it
      -- goes with something on the table (or after the meal). Popularity,
      -- co-occurrence and margin only ever rank what passed this.
      AND (r.curated_score > 0 OR EXISTS (
            SELECT 1 FROM public.reco_fit f
             WHERE f.candidate_kind = k.kind
               AND (f.venue_id IS NULL OR f.venue_id = p.venue)
               AND CASE WHEN p.placement = 'after_meal'
                        THEN f.context_kind = 'after_meal'
                        ELSE f.context_kind IN (SELECT ck.kind FROM context_kinds ck) END))
      -- Nothing that clashes with what is on the table, curated or not.
      AND NOT EXISTS (
            SELECT 1 FROM public.reco_clash c
             WHERE c.candidate_kind = k.kind
               AND (c.venue_id IS NULL OR c.venue_id = p.venue)
               AND c.context_kind IN (SELECT ck.kind FROM context_kinds ck))
      -- No second of a kind already in this round: we can add, not swap, so
      -- an "upgrade" to truffle fries next to regular fries is a second side.
      AND (p.placement = 'after_meal' OR k.kind NOT IN (SELECT kk.kind FROM cart_kinds kk))
      -- ---- Guardrails. Scoring cannot override any of these. ----
      AND public.menu_item_orderable(mi, p.now_time)
      -- Never re-suggest what is in the cart right now; beyond that, ask the
      -- role (a second coffee is ordinary café behaviour).
      AND NOT (mi.id = ANY(p.cart))
      -- No second soft drink each: once the table has as many cold drinks as
      -- people (this round or an earlier one), none is offered with the food.
      AND NOT (p.placement IN ('cart', 'item') AND mi.meal_role = 'cold_drink' AND p.cold_units >= p.people)
      AND NOT public.repeat_blocked(mi.id, _session_id)
      AND (r.rtype IN ('upgrade_to', 'add_on', 'after_meal')
           OR mi.subcategory_id NOT IN (SELECT cs.subcategory_id FROM cart_subcategories cs))
      -- Retired: shown fairly often, and even an optimistic reading of the
      -- record is below the floor.
      AND NOT (
        COALESCE(st.shown, 0) >= s.retire_after
        AND public.acceptance_retired(COALESCE(st.accepted, 0), COALESCE(st.shown, 0),
                                      pr.alpha0, pr.beta0, s.min_acceptance)
      )
      -- Never suggest around an allergen the guest has filtered out.
      AND NOT (mi.allergens && p.blocked_allergens)
      -- Coursing and the alcohol rule. See reco_role_fits.
      AND public.reco_role_fits(
            mi.meal_role,
            p.placement,
            CASE WHEN EXISTS (SELECT 1 FROM observed ob WHERE ob.item_id = mi.id)
                   OR EXISTS (SELECT 1 FROM observed_session obs WHERE obs.item_id = mi.id)
                   OR EXISTS (SELECT 1 FROM observed_family obf WHERE obf.item_id = mi.id)
                   OR EXISTS (SELECT 1 FROM learned lr WHERE lr.item_id = mi.id)
                 THEN 'observed' ELSE r.rtype END,
            r.curated_score > 0,
            p.cart,
            _session_id,
            p.at,
            p.no_alcohol)
      -- A kids' meal is for a child the menu cannot see: only when curated.
      AND (r.curated_score > 0 OR NOT EXISTS (
            SELECT 1 FROM public.subcategories ks
             WHERE ks.id = mi.subcategory_id
               AND ks.name ~* '(kid|djec|dječ|dijete|child)'))
  ),
  valued AS (
    SELECT e.*,
           e.p_accept * e.unit_cm * (1 - (1 - e.price_fit) * (1 - e.evidence)) AS expected_value
      FROM eligible e
  ),
  scored AS (
    SELECT v.*,
      -- Curated priority and observed strength stand in for "guests will take
      -- this". Once a pair has a record of its own they give way to it, down
      -- to a fifth, and measured expected profit decides. What tables taught
      -- it ranks on the curated scale: the stronger of the two counts.
      ( (1 - v.evidence) * (s.w_curated * GREATEST(v.curated_score, v.learned_score)
                            + s.w_observed * v.observed_score)
      -- ...and what its own record says, on the scale of a house priority:
      -- taken as often as suggestions are taken here = 0.5, at most 0.6 (a
      -- good house priority); beyond that, what it earns (below, with how
      -- often it is taken) decides. A pair guests keep taking rises; one they
      -- ignore falls; exploration can still give a new dish its turn.
      + v.evidence * s.w_curated * LEAST(0.6, 0.5 * v.p_accept / NULLIF(p.base_accept, 0))
      -- Expected profit: a light hand while it rests on assumptions, the
      -- full weight once the pair has a record.
      + s.w_value * (0.3 + 0.7 * v.evidence)
                  * COALESCE(v.expected_value / NULLIF(max(v.expected_value) OVER (), 0), 0)
      + (0.10 * COALESCE(v.margin_score, 0)::numeric / 100 - 0.05)
      + v.explore
      - v.load_penalty
      - v.diet_penalty
      - v.price_penalty
      - v.anchor_penalty
      - 0.15 * v.passed_over
      ) AS score,
      v.evidence * s.w_curated AS coef_cur,
      s.w_value * (0.3 + 0.7 * v.evidence) AS coef_val,
      v.unit_cm * (1 - (1 - v.price_fit) * (1 - v.evidence)) AS cm_factor,
      p.base_accept AS base_acc,
      COALESCE(LEAST(0.6, 0.5 * v.p_accept / NULLIF(p.base_accept, 0)), 0) AS cur_share,
      COALESCE(v.expected_value / NULLIF(max(v.expected_value) OVER (), 0), 0) AS ev_share
    FROM valued v
    CROSS JOIN s
    CROSS JOIN p
  ),
  /*
   * One of each before two of anything: the best stays first; after it, the
   * best of each other group with a pairing behind it (the house's, what
   * tables taught, or co-occurrence) comes before a second of any group, or a
   * filler with no pairing behind it, unless those lead by more than 0.15.
   * Burger: a drink, then fries. Pasta: a drink, then the salad. A dessert:
   * an espresso, a cappuccino — not a bottle of water for variety's sake.
   */
  diversified AS (
    SELECT sc.*,
           row_number() OVER (ORDER BY sc.score DESC, sc.price ASC, sc.id) AS overall,
           row_number() OVER (PARTITION BY sc.grp ORDER BY sc.score DESC, sc.price ASC, sc.id) AS grp_rank
      FROM scored sc
  )
  SELECT d.id, d.name, d.name_bs, d.name_ar, d.price, d.image_url, d.dietary_tags,
         d.rtype AS recommendation_type,
         d.rtype AS reason,
         d.source_item_id,
         d.suggested_quantity,
         round(d.score, 6) AS score,
         round(d.explore, 6) AS explore,
         round(d.explore_room, 6) AS explore_room,
         d.grp,
         d.kind,
         round(d.curated_score, 4) AS curated_score,
         round(d.learned_score, 4) AS learned_score,
         round(d.observed_score, 4) AS observed_score,
         round(d.evidence, 4) AS evidence,
         round(d.p_accept, 4) AS p_accept,
         (row_number() OVER (ORDER BY CASE WHEN d.overall = 1 THEN 1e9
                                           WHEN d.grp_rank = 1
                                                AND (d.curated_score > 0 OR d.learned_score > 0
                                                     OR d.rtype IN ('frequently_bought_together', 'after_meal'))
                                             THEN d.score
                                           ELSE d.score - 0.15 END DESC,
                                      d.score DESC, d.price ASC, d.id))::int AS ord,
         round(d.p_mean, 6) AS p_mean,
         round(d.p_sd, 6) AS p_sd,
         round(d.p_k, 4) AS p_k,
         round(d.base_acc, 6) AS base_accept,
         round(d.coef_cur, 6) AS coef_cur,
         round(d.coef_val, 6) AS coef_val,
         round(d.cm_factor, 6) AS cm_factor,
         round(d.score - d.coef_cur * d.cur_share - d.coef_val * d.ev_share, 6) AS score_fixed
    FROM diversified d
   ORDER BY ord
   LIMIT (SELECT lim FROM p);
$function$;

REVOKE ALL ON FUNCTION public.reco_rank_scored_v4(uuid[], text, text, int, uuid, text[], int[]) FROM PUBLIC, anon;

-- ---------------------------------------------------------------------
-- 6. Which ranker runs
-- ---------------------------------------------------------------------

/**
 * The ranker the restaurant runs (restaurant_settings.reco_learner): same
 * arguments, same columns as before. v3 is the ranker of
 * 20261031120000_reco_quality.sql, unchanged (reco_rank_scored_v3); v4 is the
 * same ranker with a posterior draw for P(taken) in place of the novelty
 * bonus (reco_rank_scored_v4).
 */
CREATE OR REPLACE FUNCTION public.reco_rank_scored(_cart_item_ids uuid[] DEFAULT '{}'::uuid[], _placement text DEFAULT 'cart'::text, _language text DEFAULT 'en'::text, _limit integer DEFAULT 4, _session_id uuid DEFAULT NULL::uuid, _exclude_allergens text[] DEFAULT '{}'::text[], _cart_quantities integer[] DEFAULT NULL::integer[])
 RETURNS TABLE(id uuid, name text, name_bs text, name_ar text, price numeric, image_url text, dietary_tags text[], recommendation_type text, reason text, source_item_id uuid, suggested_quantity integer, score numeric, explore numeric, explore_room numeric, grp text, kind text, curated_score numeric, learned_score numeric, observed_score numeric, evidence numeric, p_accept numeric, ord integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
BEGIN
  IF public.reco_learner_for(public.current_venue()) = 'v4' THEN
    RETURN QUERY
      SELECT r.id, r.name, r.name_bs, r.name_ar, r.price, r.image_url, r.dietary_tags, r.recommendation_type,
             r.reason, r.source_item_id, r.suggested_quantity, r.score, r.explore, r.explore_room, r.grp, r.kind,
             r.curated_score, r.learned_score, r.observed_score, r.evidence, r.p_accept, r.ord
        FROM public.reco_rank_scored_v4(_cart_item_ids, _placement, _language, _limit, _session_id,
                                        _exclude_allergens, _cart_quantities) r
       ORDER BY r.ord;
  ELSE
    RETURN QUERY
      SELECT r.* FROM public.reco_rank_scored_v3(_cart_item_ids, _placement, _language, _limit, _session_id,
                                                 _exclude_allergens, _cart_quantities) r
       ORDER BY r.ord;
  END IF;
END;
$function$;

REVOKE ALL ON FUNCTION public.reco_rank_scored(uuid[], text, text, int, uuid, text[], int[]) FROM PUBLIC, anon;

-- ---------------------------------------------------------------------
-- 7. The guest wrapper: the language, and the probability under v4
-- ---------------------------------------------------------------------

-- Latest: 20261031120000_reco_quality.sql. Same, plus every change marked v4.
CREATE OR REPLACE FUNCTION public.guest_get_recommendations(
  _session_id uuid,
  _session_token text,
  _cart_item_ids uuid[] DEFAULT '{}',
  _placement text DEFAULT 'cart',
  _language text DEFAULT 'en',
  _limit int DEFAULT 4,
  _exclude_allergens text[] DEFAULT '{}',
  _require_tags text[] DEFAULT '{}',
  _exclude_item_ids uuid[] DEFAULT '{}',
  _cart_quantities int[] DEFAULT NULL
)
RETURNS TABLE(
  decision_id uuid,
  id uuid,
  name text,
  name_bs text,
  name_ar text,
  price numeric,
  image_url text,
  dietary_tags text[],
  recommendation_type text,
  reason text,
  source_item_id uuid,
  suggested_quantity int
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $$
#variable_conflict use_column
DECLARE
  v_decision_id uuid;
  v_top record;
  v_candidates jsonb;
  v_arm text;
  v_experiment uuid;
  v_limit int := LEAST(GREATEST(COALESCE(_limit, 4), 1), 8);
  v_allergens text[] := COALESCE(_exclude_allergens, '{}'::text[]);
  v_cart_value numeric;
  -- Everything La Soul serves is halal and alcohol-free, so those are not
  -- filters here: a dish nobody got round to tagging "halal" is still halal
  -- and must not drop out of the suggestions for it.
  v_tags text[] := ARRAY(SELECT tg FROM unnest(COALESCE(_require_tags, '{}'::text[])) tg
                          WHERE tg NOT IN ('halal', 'alcohol_free', 'no_alcohol'));
  v_declined text[];
  v_probability numeric := 1.0;
  -- v4 (20261116130000_reco_learner_v4.sql): which ranker, and the guest's language.
  v_learner text := public.reco_learner_for(public.current_venue());
  v_lang text := CASE WHEN _language IN ('en', 'bs', 'ar') THEN _language ELSE 'en' END;
BEGIN
  PERFORM public.assert_guest_session(_session_id, _session_token);

  -- Twice in one transaction must not fail on the temp tables.
  DROP TABLE IF EXISTS pg_temp._ranked;
  DROP TABLE IF EXISTS pg_temp._scored;

  -- What the guest said no to this visit, as groups.
  v_declined := ARRAY(
    SELECT DISTINCT public.reco_kind_group(public.reco_kind(mi.name, sub.name, mi.meal_role, mi.station))
      FROM public.menu_items mi
      LEFT JOIN public.subcategories sub ON sub.id = mi.subcategory_id
     WHERE mi.id = ANY(COALESCE(_exclude_item_ids, '{}'::uuid[])));

  IF v_learner = 'v4' THEN
    CREATE TEMP TABLE _scored ON COMMIT DROP AS
      SELECT r.*, (r.grp = ANY(v_declined)) AS declined
        FROM public.reco_rank_scored_v4(
               _cart_item_ids, _placement, _language, 24, _session_id, v_allergens, _cart_quantities) r
       WHERE NOT (r.id = ANY(COALESCE(_exclude_item_ids, '{}'::uuid[])))
         AND v_tags <@ COALESCE(r.dietary_tags, '{}'::text[]);
  ELSE
    CREATE TEMP TABLE _scored ON COMMIT DROP AS
      SELECT r.*, (r.grp = ANY(v_declined)) AS declined
        FROM public.reco_rank_scored(
               _cart_item_ids, _placement, _language, 24, _session_id, v_allergens, _cart_quantities) r
       WHERE NOT (r.id = ANY(COALESCE(_exclude_item_ids, '{}'::uuid[])))
         AND v_tags <@ COALESCE(r.dietary_tags, '{}'::text[]);
  END IF;

  CREATE TEMP TABLE _ranked ON COMMIT DROP AS
    SELECT f.*, row_number() OVER (ORDER BY f.declined, f.ord) AS rnk
      FROM (SELECT sc.* FROM _scored sc ORDER BY sc.declined, sc.ord LIMIT v_limit) f;

  SELECT a.arm, a.experiment_id INTO v_arm, v_experiment
    FROM public.session_experiment_assignment a WHERE a.session_id = _session_id;

  SELECT round(sum(mi.price), 2) INTO v_cart_value
    FROM public.menu_items mi
   WHERE mi.id = ANY(COALESCE(_cart_item_ids, '{}'::uuid[]));

  -- The shortlist, not just the winner, in the order it was ranked: needed
  -- to estimate a policy you did not run.
  IF v_learner = 'v4' THEN
    -- With each candidate's posterior, so the choice can be re-run offline.
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'item_id', r.id, 'type', r.recommendation_type, 'price', r.price, 'rank', r.rnk,
             'qty', r.suggested_quantity, 'p_mean', r.p_mean, 'p_sd', r.p_sd
           ) ORDER BY r.rnk), '[]'::jsonb)
      INTO v_candidates FROM _ranked r;
  ELSE
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'item_id', r.id, 'type', r.recommendation_type, 'price', r.price, 'rank', r.rnk,
             'qty', r.suggested_quantity
           ) ORDER BY r.rnk), '[]'::jsonb)
      INTO v_candidates FROM _ranked r;
  END IF;

  SELECT * INTO v_top FROM _ranked r ORDER BY r.rnk LIMIT 1;

  /*
   * The chance this dish was chosen: it comes first when its score, with its
   * own exploration draw u (uniform within its room), beats every rival's
   * with theirs. Integrated over u at 200 points; rivals are the dishes it
   * could have lost to (the same side of "no thanks"). Without exploration
   * it is 1.
   */
  IF v_top.id IS NOT NULL AND v_learner = 'v4' THEN
    /*
     * v4: the chance this dish comes first when every rival's P(taken) is
     * drawn again from its posterior (200 joint draws). The rest of each score
     * does not depend on the draw (score_fixed); the house-scale term and the
     * expected-profit share are recomputed per draw, the latter against the
     * best of that draw. Rivals: the same side of "no thanks".
     */
    WITH c AS (SELECT * FROM _scored sc WHERE sc.declined = v_top.declined),
    pz AS (
      SELECT g.k, c.id AS cid, c.price AS cprice, c.score_fixed, c.coef_cur, c.coef_val, c.cm_factor, c.base_accept,
             LEAST(1, GREATEST(0.001, c.p_mean + c.p_k * c.p_sd
                    * sqrt(-2 * ln(1 - random())) * cos(2 * pi() * random()))) AS pp
        FROM generate_series(1, 200) g(k) CROSS JOIN c
    ),
    ev AS (
      SELECT pz.*, pz.pp * pz.cm_factor AS e, max(pz.pp * pz.cm_factor) OVER (PARTITION BY pz.k) AS emax FROM pz
    ),
    sc AS (
      SELECT ev.k, ev.cid, ev.cprice,
             ev.score_fixed + ev.coef_cur * COALESCE(LEAST(0.6, 0.5 * ev.pp / NULLIF(ev.base_accept, 0)), 0)
               + ev.coef_val * COALESCE(ev.e / NULLIF(ev.emax, 0), 0) AS s
        FROM ev
    ),
    win AS (SELECT DISTINCT ON (sc.k) sc.k, sc.cid FROM sc ORDER BY sc.k, sc.s DESC, sc.cprice ASC, sc.cid)
    SELECT round(count(*) FILTER (WHERE win.cid = v_top.id)::numeric / 200, 4) INTO v_probability FROM win;
  ELSIF v_top.id IS NOT NULL THEN
    SELECT COALESCE(round(avg(x.pr), 4), 1.0) INTO v_probability
      FROM (
        SELECT g.u,
               CASE WHEN bool_or(o.f <= 0) THEN 0 ELSE exp(sum(ln(GREATEST(o.f, 1e-300)))) END AS pr
          FROM (SELECT (k - 0.5) / 200.0 AS u
                  FROM generate_series(1, CASE WHEN v_top.explore_room > 0 THEN 200 ELSE 1 END) k) g
          CROSS JOIN LATERAL (
            SELECT CASE
                     WHEN c.explore_room > 0 THEN
                       LEAST(1, GREATEST(0, ((v_top.score - v_top.explore) + v_top.explore_room * g.u
                                             - (c.score - c.explore)) / c.explore_room))
                     WHEN (c.score - c.explore) < (v_top.score - v_top.explore) + v_top.explore_room * g.u THEN 1
                     WHEN (c.score - c.explore) = (v_top.score - v_top.explore) + v_top.explore_room * g.u
                          AND c.ord > v_top.ord THEN 1
                     ELSE 0
                   END AS f
              FROM _scored c
             WHERE c.id <> v_top.id AND c.declined = v_top.declined
          ) o
         GROUP BY g.u
      ) x;
  END IF;

  INSERT INTO public.recommendation_decisions(
    session_id, placement, policy_version, experiment_id, arm,
    candidates, chosen_item_id, source_item_id, recommendation_type, action_probability,
    cart_value, suggested_quantity, language)
  VALUES (
    _session_id, _placement, public.reco_policy_version(), v_experiment, v_arm,
    v_candidates, v_top.id, v_top.source_item_id, v_top.recommendation_type,
    v_probability,
    COALESCE(v_cart_value, 0),
    v_top.suggested_quantity,
    v_lang)
  RETURNING recommendation_decisions.id INTO v_decision_id;

  RETURN QUERY
    SELECT v_decision_id, r.id, r.name, r.name_bs, r.name_ar, r.price, r.image_url,
           r.dietary_tags, r.recommendation_type, r.reason, r.source_item_id, r.suggested_quantity
      FROM _ranked r
     ORDER BY r.rnk;
END;
$$;

REVOKE ALL ON FUNCTION public.guest_get_recommendations(uuid, text, uuid[], text, text, int, text[], text[], uuid[], int[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.guest_get_recommendations(uuid, text, uuid[], text, text, int, text[], text[], uuid[], int[]) TO anon, authenticated;

-- ---------------------------------------------------------------------
-- 8. The old sampler's switch, under v4
-- ---------------------------------------------------------------------

-- Latest: 20261028100000_two_restaurants_context.sql.
CREATE OR REPLACE FUNCTION public.maybe_enable_sampling()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_enabled boolean;
  v_ready boolean;
  v_version text;
  v_home uuid := public.current_venue();
  v_prev text := current_setting('lasoul.venue', true);
  v record;
  v_result jsonb;
  v_home_result jsonb;
  v_changed jsonb;
BEGIN
  IF NOT public.is_trusted_caller() THEN
    RAISE EXCEPTION 'Only staff can change the ranking policy' USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Each restaurant on its own gate and its own settings. The nightly job has
  -- no user and covers every restaurant; a signed-in caller only those they
  -- work at.
  FOR v IN
    SELECT ve.id FROM public.venues ve
     WHERE auth.uid() IS NULL OR public.can_staff(ve.id)
     ORDER BY ve.id
  LOOP
    PERFORM public.use_venue(v.id);

    -- v4 always samples (on the exploration dial): nothing to switch, and the
    -- running experiment is not closed for a change that did not happen.
    IF public.reco_learner_for(v.id) = 'v4' THEN
      v_result := jsonb_build_object('changed', false, 'reason', 'v4_samples_always');
      IF v.id = v_home OR v_home_result IS NULL THEN
        v_home_result := v_result;
      END IF;
      CONTINUE;
    END IF;

    v_enabled := NULL;
    SELECT COALESCE(reco_sampling_enabled, false) INTO v_enabled
      FROM public.restaurant_settings WHERE venue_id = v.id;

    IF v_enabled THEN
      v_result := jsonb_build_object('changed', false, 'reason', 'already_on');
    ELSE
      SELECT (public.bandit_readiness() ->> 'ready')::boolean INTO v_ready;
      IF NOT COALESCE(v_ready, false) THEN
        v_result := jsonb_build_object('changed', false, 'reason', 'gate_not_passed');
      ELSE
        UPDATE public.restaurant_settings SET reco_sampling_enabled = true WHERE venue_id = v.id;
        v_version := public.reco_policy_version();

        -- A policy change invalidates the running comparison, so it is closed.
        -- Starting the next one is a deliberate act by a manager.
        UPDATE public.experiments SET ended_at = now(),
               notes = COALESCE(notes, '') || ' [closed automatically: ranking policy changed to ' || v_version || ']'
         WHERE ended_at IS NULL AND venue_id = v.id;

        PERFORM public.write_audit('reco.sampling_enabled', 'settings', NULL::uuid, NULL::jsonb,
          jsonb_build_object('policy_version', v_version),
          'bandit_readiness gate passed');

        v_result := jsonb_build_object('changed', true, 'policy_version', v_version);
        v_changed := COALESCE(v_changed, v_result);
      END IF;
    END IF;

    IF v.id = v_home OR v_home_result IS NULL THEN
      v_home_result := v_result;
    END IF;
  END LOOP;

  -- The rest of the caller's transaction is about the restaurant it was about.
  PERFORM set_config('lasoul.venue', COALESCE(v_prev, ''), true);

  -- One answer, as before: a change anywhere, otherwise this restaurant's reason.
  RETURN COALESCE(v_changed, v_home_result,
                  jsonb_build_object('changed', false, 'reason', 'gate_not_passed'));
END;
$function$;

-- ---------------------------------------------------------------------
-- 8b. The readiness gate says sampling is on under v4
-- ---------------------------------------------------------------------

-- Latest: 20261028100000_two_restaurants_context.sql. The admin's "How the app is
-- choosing suggestions" reads sampling_enabled from here.
CREATE OR REPLACE FUNCTION public.bandit_readiness()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_venue uuid := public.current_venue();
  v_decisions bigint;
  v_impressions bigint;
  v_verified_conversions bigint;
  v_with_probability bigint;
  v_pairs_with_support bigint;
  v_stats_shown bigint;
  v_stats_ledger bigint;
  v_sampling boolean;
  v_min_decisions constant int := 2000;
  v_min_pairs constant int := 15;
  v_checks jsonb;
BEGIN
  -- Trusted rather than staff-only: maybe_enable_sampling() calls this from
  -- the nightly job. Signed-in staff read only a restaurant they work at.
  IF NOT public.is_trusted_caller()
     OR (public.is_staff_member() AND NOT public.can_staff(v_venue)) THEN
    RAISE EXCEPTION 'Only staff can read the readiness gate' USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- v4 samples whenever the exploration dial is above 0.
  SELECT COALESCE(reco_sampling_enabled, false)
         OR (COALESCE(reco_learner, 'v3') = 'v4' AND COALESCE(reco_exploration, 15) > 0)
    INTO v_sampling
    FROM public.restaurant_settings WHERE venue_id = v_venue;

  SELECT count(*), count(*) FILTER (WHERE d.action_probability IS NOT NULL)
    INTO v_decisions, v_with_probability
    FROM public.recommendation_decisions d
    JOIN public.table_sessions ts ON ts.id = d.session_id
   WHERE ts.venue_id = v_venue;

  SELECT count(*) INTO v_impressions
    FROM public.recommendation_impressions i
    JOIN public.recommendation_decisions d ON d.id = i.decision_id
    JOIN public.table_sessions ts ON ts.id = d.session_id
   WHERE ts.venue_id = v_venue;

  SELECT count(*) INTO v_verified_conversions
    FROM public.suggestion_conversions sc
    JOIN public.completed_orders co ON co.id = sc.order_id
    JOIN public.orders o ON o.id = co.id
   WHERE sc.decision_id IS NOT NULL
     AND o.venue_id = v_venue;

  SELECT count(*) INTO v_pairs_with_support
    FROM (
      SELECT d.chosen_item_id, d.source_item_id
        FROM public.recommendation_decisions d
        JOIN public.table_sessions ts ON ts.id = d.session_id
        JOIN public.recommendation_impressions i ON i.decision_id = d.id
       WHERE d.chosen_item_id IS NOT NULL
         AND ts.venue_id = v_venue
       GROUP BY d.chosen_item_id, d.source_item_id
      HAVING count(*) >= 50
    ) x;

  SELECT COALESCE(sum(st.shown), 0), COALESCE(sum(st.shown_ledger), 0)
    INTO v_stats_shown, v_stats_ledger
    FROM public.suggestion_stats st
    JOIN public.menu_items mi ON mi.id = st.recommended_item_id
   WHERE st.daypart IS NULL
     AND mi.venue_id = v_venue;

  v_checks := jsonb_build_array(
    jsonb_build_object(
      'check', 'impressions_are_server_verified', 'pass', true,
      'note', 'recommendation_impressions is written server-side and deduped by primary key'),
    jsonb_build_object(
      'check', 'acceptance_linked_to_paid_outcome', 'pass', true,
      'note', 'suggestion_conversions.decision_id joins to completed_orders'),
    jsonb_build_object(
      'check', 'stats_learn_from_ledger',
      'pass', v_stats_shown > 0 AND v_stats_ledger >= 0.9 * v_stats_shown,
      'have', v_stats_ledger, 'of', v_stats_shown,
      'note', format('%s of %s counted sightings in suggestion_stats come from the server ledger; '
                     'browser-era rows age out of the 90-day window', v_stats_ledger, v_stats_shown)),
    jsonb_build_object(
      'check', 'action_probabilities_logged',
      'pass', v_decisions = 0 OR v_with_probability = v_decisions,
      'note', format('%s of %s decisions carry a propensity', v_with_probability, v_decisions)),
    jsonb_build_object(
      'check', 'enough_decisions', 'pass', v_decisions >= v_min_decisions,
      'have', v_decisions, 'need', v_min_decisions),
    jsonb_build_object(
      'check', 'enough_pairs_with_support', 'pass', v_pairs_with_support >= v_min_pairs,
      'have', v_pairs_with_support, 'need', v_min_pairs,
      'note', 'distinct pairs with 50+ verified impressions each'),
    jsonb_build_object(
      'check', 'conversions_observed', 'pass', v_verified_conversions > 0,
      'have', v_verified_conversions)
  );

  RETURN jsonb_build_object(
    'ready', NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_checks) c WHERE (c ->> 'pass')::boolean IS NOT TRUE),
    'checks', v_checks,
    'decisions', v_decisions,
    'impressions', v_impressions,
    'verified_conversions', v_verified_conversions,
    'sampling_enabled', v_sampling,
    'policy_version', public.reco_policy_version(),
    'note', CASE WHEN v_sampling
      THEN 'Sampling is live. Propensities are not logged as numbers; the '
           'posterior inputs per candidate are, so they can be reconstructed.'
      ELSE 'Until every check passes the fixed ranker stays. A bandit fed '
           'unreliable counts learns to maximise the noise in them.' END
  );
END;
$function$;

-- ---------------------------------------------------------------------
-- 9. The refresh learns the per-language counts too
-- ---------------------------------------------------------------------

-- Latest: 20261031100000_admin_separation.sql.
CREATE OR REPLACE FUNCTION public.refresh_menu_intelligence()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_pairs int;
  v_session_pairs int;
  v_stats int;
  v_context int;
  v_learning jsonb;
  v_result jsonb;
  v_last public.maintenance_runs;
  v_mark text := COALESCE(current_setting('lasoul.paced_refresh', true), '');
BEGIN
  IF NOT public.is_trusted_caller() THEN
    RAISE EXCEPTION 'Only staff can refresh menu intelligence' USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF NOT public.is_owner_or_scheduler() THEN
    SELECT * INTO v_last FROM public.maintenance_runs WHERE job = 'menu_intelligence';
    IF v_last.last_run_at > now() - interval '10 minutes' THEN
      RETURN v_last.last_result || jsonb_build_object('paced', true);
    END IF;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('lasoul.menu_intelligence'));

  v_pairs := public.refresh_menu_affinity(365, 2);
  v_session_pairs := public.refresh_session_affinity(365, 2);
  v_stats := public.refresh_suggestion_stats(90);
  v_context := public.refresh_suggestion_context_stats(90);
  PERFORM set_config('lasoul.paced_refresh', 'on', true);
  v_learning := public.rebuild_reco_learning(365);
  PERFORM set_config('lasoul.paced_refresh', v_mark, true);

  v_result := jsonb_build_object(
    'pairs', v_pairs,
    'session_pairs', v_session_pairs,
    'section_pairs', (SELECT count(*) FROM public.subcategory_affinity WHERE eb05 > 1),
    'suggestion_rows', v_stats,
    'context_rows', v_context,
    'learned_visits', v_learning -> 'visits',
    'refreshed_at', now());

  INSERT INTO public.maintenance_runs(job, last_run_at, last_result)
  VALUES ('menu_intelligence', now(), v_result)
  ON CONFLICT (job) DO UPDATE SET last_run_at = now(), last_result = v_result;

  RETURN v_result;
END;
$$;

REVOKE ALL ON FUNCTION public.refresh_menu_intelligence() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.refresh_menu_intelligence() TO authenticated;
